script:
/**
 * Purchase Order - Items Spreadsheet
 * Frappe/ERPNext v16 Client Script (DocType: Purchase Order).
 *
 * Turns the standard Items grid into a compact, Excel-like sheet:
 *  - resizable + persisted column widths
 *  - sticky item_code/row-check on the left, edit button on the right
 *  - a live totals footer (Qty, Trade Offer, Amount)
 *  - row filter, column show/hide, fullscreen
 *  - arrow-key navigation and copy/paste across cells
 *
 * Tuned specifically for this app's Purchase Order Item columns
 * (custom_vendor_rate, custom_mrp, custom_scheme_qty, custom_discount_per,
 * custom_trade_offer_total, custom_gst_formula/_per, custom_advance_tax_formula/_per,
 * custom_fed_formula/_per, custom_is_3rd_schedule) - see aimatic/branch_management
 * and the "PurchaseOrderCalculation" server script for what feeds these fields.
 */
(function () {
	"use strict";

	if (typeof frappe === "undefined" || typeof jQuery === "undefined") {
		return;
	}

	const $ = jQuery;
	const NS = "po-items-sheet";
	const STYLE_ID = `${NS}-style`;
	const WIDTHS_KEY = `${NS}.widths.v1`;
	const HIDDEN_COLS_KEY = `${NS}.hidden-columns.v1`;
	const MIN_WIDTH = 46;
	const MAX_WIDTH = 480;

	const SEL = {
		CONTAINER: ".form-grid-container",
		HEAD_ROW: ".grid-heading-row",
		BODY: ".grid-body",
		GRID_ROW: ".grid-row",
		DATA_ROW: ".data-row",
		COL: ".col",
	};

	// Default column widths, keyed by fieldname (falls back to a
	// label-length estimate for anything not listed here).
	const DEFAULT_WIDTHS = {
		row_check: 34,
		row_index: 44,
		item_code: 150,
		item_name: 190,
		description: 200,
		schedule_date: 100,
		qty: 70,
		custom_scheme_qty: 84,
		uom: 64,
		custom_vendor_rate: 100,
		custom_mrp: 90,
		custom_discount_per: 90,
		custom_trade_offer_total: 110,
		custom_is_3rd_schedule: 46,
		custom_gst_formula: 130,
		custom_gst_per: 74,
		custom_advance_tax_formula: 130,
		custom_advance_tax_per: 90,
		custom_fed_formula: 110,
		custom_fed_per: 74,
		rate: 92,
		amount: 106,
		warehouse: 140,
		btn_open_row: 36,
	};

	// Columns pinned to the left/right edge of the sheet while scrolling.
	const STICKY_LEFT = ["row_check", "row_index", "item_code"];
	const STICKY_RIGHT = ["btn_open_row"];

	// Explicit footer totals - deliberately not a "total anything that
	// looks numeric" heuristic, since most of this grid's columns are
	// per-unit inputs (rates/percentages) that should never be summed.
	const FOOTER_TOTALS = [
		{ field: "qty", label: "Qty", precision: 0 },
		{ field: "custom_trade_offer_total", label: "Trade Offer", precision: 2 },
		{ field: "amount", label: "Amount", precision: 2 },
	];

	const util = {
		debounce(fn, wait) {
			let timer = null;
			return function (...args) {
				clearTimeout(timer);
				timer = setTimeout(() => fn.apply(this, args), wait);
			};
		},

		toFloat(value) {
			if (value === null || value === undefined || value === "") return 0;
			const n = typeof value === "number" ? value : Number.parseFloat(String(value).replace(/,/g, ""));
			return Number.isFinite(n) ? n : 0;
		},

		formatNumber(value, precision) {
			if (typeof format_number === "function") {
				return format_number(value, null, precision);
			}
			return value.toFixed(precision);
		},

		loadJSON(key) {
			try {
				return JSON.parse(localStorage.getItem(key)) || {};
			} catch (e) {
				return {};
			}
		},

		saveJSON(key, value) {
			try {
				localStorage.setItem(key, JSON.stringify(value));
			} catch (e) {
				/* storage full/unavailable - widths just won't persist */
			}
		},

		escapeHtml(value) {
			return String(value == null ? "" : value).replace(/[&<>"']/g, (ch) => ({
				"&": "&amp;",
				"<": "&lt;",
				">": "&gt;",
				'"': "&quot;",
				"'": "&#39;",
			}[ch]));
		},
	};

	class PurchaseOrderItemsSheet {
		constructor(frm) {
			this.frm = frm;
			this.grid = frm.fields_dict.items && frm.fields_dict.items.grid;
			this.$wrapper = this.grid ? $(this.grid.wrapper) : $();
			this.widths = util.loadJSON(WIDTHS_KEY);
			this.hiddenColumns = util.loadJSON(HIDDEN_COLS_KEY);
			this.filterText = "";
			this.activeCell = null;
			this.isFullscreen = false;
			this.destroyed = false;
			this.observer = null;
			this.scheduleRender = util.debounce(() => this.render(), 100);
			this.onKeydown = this.onKeydown.bind(this);
			this.onDocClick = this.onDocClick.bind(this);
		}

		mount() {
			if (!this.grid || !this.$wrapper.length) {
				return;
			}

			injectStyles();
			this.$wrapper.addClass(NS).data(NS, this);
			this.buildToolbar();
			this.bindEvents();
			this.observeGrid();
			document.addEventListener("keydown", this.onKeydown);
			document.addEventListener("click", this.onDocClick);
			this.render();
		}

		destroy() {
			this.destroyed = true;
			if (this.observer) {
				this.observer.disconnect();
			}
			document.removeEventListener("keydown", this.onKeydown);
			document.removeEventListener("click", this.onDocClick);
			$("body").removeClass(`${NS}--locked`);
			this.$wrapper.off(`.${NS}`);
			this.$wrapper.removeClass(`${NS} ${NS}--fullscreen`).removeData(NS);
			this.$wrapper.children(`.${NS}__toolbar`).remove();
			this.$wrapper.find(`.${NS}__footer`).remove();
			this.hideColumnMenu();
		}

		// -- setup ------------------------------------------------------

		buildToolbar() {
			if (this.$wrapper.children(`.${NS}__toolbar`).length) {
				return;
			}

			this.$wrapper.prepend(`
				<div class="${NS}__toolbar">
					<strong class="${NS}__title">Items Spreadsheet</strong>
					<span class="${NS}__count"></span>
					<span class="${NS}__spacer"></span>
					<input type="search" class="${NS}__filter" placeholder="Filter items...">
					<button type="button" class="btn btn-default btn-xs ${NS}__columns-btn">Columns</button>
					<button type="button" class="btn btn-default btn-xs ${NS}__reset-btn">Reset Widths</button>
					<button type="button" class="btn btn-primary btn-xs ${NS}__fullscreen-btn">&#x26F6; Full Screen</button>
				</div>
			`);
		}

		bindEvents() {
			this.$wrapper.off(`.${NS}`);

			this.$wrapper.on(`click.${NS}`, `.${NS}__fullscreen-btn`, () => {
				this.toggleFullscreen(!this.isFullscreen);
			});

			this.$wrapper.on(`input.${NS}`, `.${NS}__filter`, (e) => {
				this.filterText = e.currentTarget.value || "";
				this.applyFilter();
				this.updateCount();
				this.updateFooter();
			});

			this.$wrapper.on(`click.${NS}`, `.${NS}__reset-btn`, () => {
				this.widths = {};
				this.hiddenColumns = {};
				util.saveJSON(WIDTHS_KEY, this.widths);
				util.saveJSON(HIDDEN_COLS_KEY, this.hiddenColumns);
				this.render();
			});

			this.$wrapper.on(`click.${NS}`, `.${NS}__columns-btn`, (e) => {
				e.stopPropagation();
				this.toggleColumnMenu(e.currentTarget);
			});

			this.$wrapper.on(`mousedown.${NS}`, `.${NS}__resize-handle`, (e) => {
				this.startResize(e);
			});

			this.$wrapper.on(`dblclick.${NS}`, `.${NS}__resize-handle`, (e) => {
				e.preventDefault();
				const col = $(e.currentTarget).closest(SEL.COL)[0];
				this.autoFitColumn(this.headerCells().index(col));
			});

			this.$wrapper.on(`click.${NS}`, `${SEL.BODY} ${SEL.DATA_ROW} > ${SEL.COL}`, (e) => {
				this.setActiveCell(e.currentTarget);
			});

			this.$wrapper.on(`keydown.${NS}`, SEL.CONTAINER, (e) => this.onGridKeydown(e));

			this.$wrapper.on(
				`input.${NS} change.${NS}`,
				`${SEL.BODY} input, ${SEL.BODY} select, ${SEL.BODY} textarea`,
				() => this.scheduleRender()
			);
		}

		observeGrid() {
			const body = this.$wrapper.find(SEL.BODY)[0];
			if (!body) {
				return;
			}
			this.observer = new MutationObserver(() => this.scheduleRender());
			this.observer.observe(body, { childList: true, subtree: true });
		}

		// -- render loop -------------------------------------------------

		render() {
			if (this.destroyed || !this.isReady()) {
				return;
			}

			this.$wrapper.find(SEL.CONTAINER).attr("tabindex", "0");
			this.syncColumnWidths();
			this.applyHiddenColumns();
			this.syncStickyColumns();
			this.applyFilter();
			this.ensureFooter();
			this.updateCount();
			this.updateFooter();
		}

		isReady() {
			return this.$wrapper.find(SEL.CONTAINER).length && this.headerCells().length;
		}

		headerCells() {
			return this.$wrapper.find(`${SEL.HEAD_ROW} ${SEL.DATA_ROW}`).first().children(SEL.COL);
		}

		bodyRows() {
			return this.$wrapper.find(`${SEL.BODY} ${SEL.GRID_ROW}`);
		}

		rowCells(row) {
			return $(row).find(`${SEL.DATA_ROW} > ${SEL.COL}`);
		}

		columnKey(col, index) {
			const field = this.fieldname(col);
			if (field) return field;
			if (col.classList.contains("row-check")) return "row_check";
			if (col.classList.contains("row-index")) return "row_index";
			if (col.classList.contains("btn-open-row") || $(col).find(".btn-open-row").length) return "btn_open_row";
			return `col_${index}`;
		}

		fieldname(col) {
			return (col && col.dataset && col.dataset.fieldname) || "";
		}

		docfield(fieldname) {
			if (!fieldname || !this.grid) return null;
			if (this.grid.fields_map && this.grid.fields_map[fieldname]) {
				return this.grid.fields_map[fieldname];
			}
			return null;
		}

		// -- column widths -------------------------------------------------

		defaultWidth(col, key) {
			if (DEFAULT_WIDTHS[key]) return DEFAULT_WIDTHS[key];
			const label = (col.textContent || "").trim();
			return Math.max(70, Math.min(160, label.length * 8 + 30));
		}

		widthFor(col, key) {
			return this.widths[key] || this.defaultWidth(col, key);
		}

		syncColumnWidths() {
			const headers = this.headerCells();
			let totalWidth = 0;

			headers.each((index, col) => {
				const key = this.columnKey(col, index);
				const width = this.widthFor(col, key);
				totalWidth += width;

				this.setCellWidth(col, width);
				this.ensureResizeHandle(col);

				this.bodyRows().each((_, row) => {
					this.setCellWidth(this.rowCells(row).get(index), width);
				});

				this.setCellWidth(this.footerCells().get(index), width);
			});

			this.$wrapper
				.find(`${SEL.HEAD_ROW} ${SEL.DATA_ROW}, ${SEL.BODY} ${SEL.DATA_ROW}, .${NS}__footer-row`)
				.css({ width: `${totalWidth}px`, minWidth: `${totalWidth}px` });
		}

		setCellWidth(cell, width) {
			if (!cell) return;
			$(cell).css({ flex: `0 0 ${width}px`, width: `${width}px`, minWidth: `${width}px`, maxWidth: `${width}px` });
		}

		ensureResizeHandle(col) {
			if ($(col).children(`.${NS}__resize-handle`).length) return;
			$(`<span class="${NS}__resize-handle" aria-hidden="true"></span>`).appendTo(col);
		}

		startResize(e) {
			e.preventDefault();
			e.stopPropagation();

			const col = $(e.currentTarget).closest(SEL.COL)[0];
			const index = this.headerCells().index(col);
			const key = this.columnKey(col, index);
			const startX = e.clientX;
			const startWidth = col.getBoundingClientRect().width || this.widthFor(col, key);

			const onMove = (moveEvent) => {
				const next = Math.max(MIN_WIDTH, Math.min(MAX_WIDTH, startWidth + moveEvent.clientX - startX));
				this.widths[key] = Math.round(next);
				this.syncColumnWidths();
				this.syncStickyColumns();
			};

			const onUp = () => {
				document.removeEventListener("mousemove", onMove);
				document.removeEventListener("mouseup", onUp);
				util.saveJSON(WIDTHS_KEY, this.widths);
				this.updateFooter();
			};

			document.addEventListener("mousemove", onMove);
			document.addEventListener("mouseup", onUp);
		}

		autoFitColumn(index) {
			const col = this.headerCells().get(index);
			if (!col) return;

			const key = this.columnKey(col, index);
			let width = col.scrollWidth + 20;
			this.bodyRows().each((_, row) => {
				const cell = this.rowCells(row).get(index);
				if (cell) width = Math.max(width, cell.scrollWidth + 20);
			});

			this.widths[key] = Math.max(MIN_WIDTH, Math.min(MAX_WIDTH, Math.ceil(width)));
			util.saveJSON(WIDTHS_KEY, this.widths);
			this.render();
		}

		// -- sticky columns ------------------------------------------------

		syncStickyColumns() {
			const headers = this.headerCells();

			this.$wrapper
				.find(`.${NS}__sticky-left, .${NS}__sticky-right`)
				.removeClass(`${NS}__sticky-left ${NS}__sticky-right`)
				.css({ left: "", right: "" });

			let offset = 0;
			headers.each((index, col) => {
				const key = this.columnKey(col, index);
				if (this.hiddenColumns[key] || !STICKY_LEFT.includes(key)) return;

				this.columnCells(index).addClass(`${NS}__sticky-left`).css("left", `${offset}px`);
				offset += this.widthFor(col, key);
			});

			offset = 0;
			const reversed = headers.toArray().slice().reverse();
			reversed.forEach((col) => {
				const index = headers.index(col);
				const key = this.columnKey(col, index);
				if (this.hiddenColumns[key] || !STICKY_RIGHT.includes(key)) return;

				this.columnCells(index).addClass(`${NS}__sticky-right`).css("right", `${offset}px`);
				offset += this.widthFor(col, key);
			});
		}

		columnCells(index) {
			const cells = [this.headerCells().get(index)];
			this.bodyRows().each((_, row) => cells.push(this.rowCells(row).get(index)));
			cells.push(this.footerCells().get(index));
			return $(cells.filter(Boolean));
		}

		// -- column show/hide -----------------------------------------------

		applyHiddenColumns() {
			this.headerCells().each((index, col) => {
				const key = this.columnKey(col, index);
				this.columnCells(index).toggleClass(`${NS}__col-hidden`, !!this.hiddenColumns[key]);
			});
		}

		toggleColumnMenu(button) {
			if (this.$menu && this.$menu.length) {
				this.hideColumnMenu();
				return;
			}

			const items = this.headerCells()
				.toArray()
				.map((col, index) => {
					const key = this.columnKey(col, index);
					if (key === "row_check" || key === "row_index" || key === "btn_open_row") return null;
					const df = this.docfield(this.fieldname(col));
					const label = (df && df.label) || (col.textContent || "").trim() || key;
					return { key, label, hidden: !!this.hiddenColumns[key] };
				})
				.filter(Boolean);

			const html = `
				<div class="${NS}__menu" role="menu">
					<div class="${NS}__menu-title">Show / hide columns</div>
					${items
						.map(
							(item) => `
						<label class="${NS}__menu-option">
							<input type="checkbox" class="${NS}__menu-toggle" data-key="${util.escapeHtml(item.key)}" ${item.hidden ? "" : "checked"}>
							<span>${util.escapeHtml(item.label)}</span>
						</label>`
						)
						.join("")}
				</div>
			`;

			this.$menu = $(html).appendTo(document.body);
			this.$menu.on("change", `.${NS}__menu-toggle`, (e) => {
				const key = e.currentTarget.dataset.key;
				this.hiddenColumns[key] = !e.currentTarget.checked;
				util.saveJSON(HIDDEN_COLS_KEY, this.hiddenColumns);
				this.render();
			});

			const rect = button.getBoundingClientRect();
			this.$menu.css({
				left: Math.max(8, Math.min(rect.left, window.innerWidth - this.$menu.outerWidth() - 8)),
				top: rect.bottom + 6,
			});
		}

		hideColumnMenu() {
			if (this.$menu) {
				this.$menu.remove();
				this.$menu = null;
			}
		}

		onDocClick(e) {
			if ($(e.target).closest(`.${NS}__menu, .${NS}__columns-btn`).length) return;
			this.hideColumnMenu();
		}

		// -- filter ----------------------------------------------------------

		applyFilter() {
			const needle = this.filterText.trim().toLowerCase();
			const items = Array.isArray(this.frm.doc.items) ? this.frm.doc.items : [];

			this.bodyRows().each((index, row) => {
				if (!needle) {
					row.classList.remove(`${NS}__row-hidden`);
					return;
				}
				const item = items[index] || {};
				const haystack = `${item.item_code || ""} ${item.item_name || ""} ${item.description || ""}`.toLowerCase();
				row.classList.toggle(`${NS}__row-hidden`, !haystack.includes(needle));
			});
		}

		visibleRows() {
			return this.bodyRows().not(`.${NS}__row-hidden`);
		}

		updateCount() {
			const total = Array.isArray(this.frm.doc.items) ? this.frm.doc.items.length : 0;
			const visible = this.filterText ? this.visibleRows().length : total;
			const label = this.filterText && visible !== total ? `${visible} / ${total} rows` : `${total} ${total === 1 ? "row" : "rows"}`;
			this.$wrapper.find(`.${NS}__count`).text(label);
		}

		// -- footer totals -----------------------------------------------------

		footerCells() {
			return this.$wrapper.find(`.${NS}__footer-row > ${SEL.COL}`);
		}

		ensureFooter() {
			const container = this.$wrapper.find(SEL.CONTAINER).first();
			if (!container.length) return;

			let footer = container.children(`.${NS}__footer`);
			if (!footer.length) {
				footer = $(`<div class="${NS}__footer"><div class="col grid-row data-row ${NS}__footer-row"></div></div>`);
				container.append(footer);
			}

			const headers = this.headerCells();
			const row = footer.find(`.${NS}__footer-row`);

			if (row.children().length !== headers.length) {
				row.empty();
				headers.each(() => row.append('<div class="col"></div>'));
			}
		}

		updateFooter() {
			const headers = this.headerCells();
			const cells = this.footerCells();
			const items = Array.isArray(this.frm.doc.items) ? this.frm.doc.items : [];
			const rows = this.filterText
				? this.visibleRowIndexes().map((i) => items[i]).filter(Boolean)
				: items;

			let labelWritten = false;

			headers.each((index, col) => {
				const cell = cells.get(index);
				if (!cell) return;

				const key = this.columnKey(col, index);
				const total = FOOTER_TOTALS.find((t) => t.field === key);

				cell.textContent = "";
				cell.classList.remove(`${NS}__footer-label`, `${NS}__footer-value`);

				if (total) {
					const sum = rows.reduce((acc, row) => acc + util.toFloat(row[total.field]), 0);
					cell.textContent = util.formatNumber(sum, total.precision);
					cell.title = `${total.label}: ${cell.textContent}`;
					cell.classList.add(`${NS}__footer-value`);
				} else if (!labelWritten && key !== "row_check" && key !== "row_index") {
					cell.textContent = this.filterText && rows.length !== items.length ? `Totals (${rows.length}/${items.length})` : "Totals";
					cell.classList.add(`${NS}__footer-label`);
					labelWritten = true;
				}
			});
		}

		visibleRowIndexes() {
			const indexes = [];
			this.bodyRows().each((index, row) => {
				if (!row.classList.contains(`${NS}__row-hidden`)) indexes.push(index);
			});
			return indexes;
		}

		// -- fullscreen -----------------------------------------------------

		toggleFullscreen(enable) {
			this.isFullscreen = !!enable;
			this.$wrapper.toggleClass(`${NS}--fullscreen`, this.isFullscreen);
			$("body").toggleClass(`${NS}--locked`, this.isFullscreen);
			this.$wrapper
				.find(`.${NS}__fullscreen-btn`)
				.html(this.isFullscreen ? "&times; Close" : "&#x26F6; Full Screen");
			setTimeout(() => this.render(), 30);
		}

		// -- keyboard nav + copy/paste -----------------------------------------

		setActiveCell(cell) {
			if (!cell) return;
			this.$wrapper.find(`.${NS}__active-cell`).removeClass(`${NS}__active-cell`);
			cell.classList.add(`${NS}__active-cell`);

			const row = $(cell).closest(SEL.GRID_ROW)[0];
			this.activeCell = {
				rowIndex: this.bodyRows().index(row),
				colIndex: $(cell).closest(SEL.DATA_ROW).children(SEL.COL).index(cell),
				cell,
			};
		}

		onGridKeydown(e) {
			if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "c") {
				e.preventDefault();
				this.copyActiveCell();
				return;
			}
			if ((e.ctrlKey || e.metaKey) && e.key.toLowerCase() === "v") {
				e.preventDefault();
				this.pasteFromClipboard();
				return;
			}

			const moves = { ArrowLeft: [0, -1], ArrowRight: [0, 1], ArrowUp: [-1, 0], ArrowDown: [1, 0] };
			if (moves[e.key]) {
				e.preventDefault();
				this.moveActiveCell(moves[e.key][0], moves[e.key][1]);
			}
		}

		onKeydown(e) {
			if (e.key === "Escape") {
				if (this.isFullscreen) {
					this.toggleFullscreen(false);
				}
				this.hideColumnMenu();
			}
		}

		moveActiveCell(rowDelta, colDelta) {
			const visibleHeaders = this.headerCells()
				.toArray()
				.map((col, index) => ({ col, index }))
				.filter((entry) => !entry.col.classList.contains(`${NS}__col-hidden`));

			if (!this.activeCell) {
				const firstRow = this.visibleRows().get(0);
				const firstCell = firstRow && this.rowCells(firstRow).get(visibleHeaders[0] ? visibleHeaders[0].index : 0);
				this.setActiveCell(firstCell);
				return;
			}

			const rows = this.visibleRows();
			const currentRowPos = rows.index(this.bodyRows().get(this.activeCell.rowIndex));
			const nextRowPos = Math.max(0, Math.min(rows.length - 1, currentRowPos + rowDelta));
			const nextRow = rows.get(nextRowPos);
			if (!nextRow) return;

			const currentColPos = visibleHeaders.findIndex((entry) => entry.index === this.activeCell.colIndex);
			const nextColPos = Math.max(0, Math.min(visibleHeaders.length - 1, currentColPos + colDelta));
			const nextCol = visibleHeaders[nextColPos];
			if (!nextCol) return;

			const nextCell = this.rowCells(nextRow).get(nextCol.index);
			if (nextCell) {
				this.setActiveCell(nextCell);
				nextCell.scrollIntoView({ block: "nearest", inline: "nearest" });
			}
		}

		async copyActiveCell() {
			if (!this.activeCell) return;
			const field = this.fieldname(this.headerCells().get(this.activeCell.colIndex));
			const row = this.frm.doc.items[this.activeCell.rowIndex];
			if (!field || !row) return;

			try {
				await navigator.clipboard.writeText(row[field] == null ? "" : String(row[field]));
				frappe.show_alert({ message: __("Copied"), indicator: "green" }, 2);
			} catch (e) {
				/* clipboard blocked - silently ignore */
			}
		}

		async pasteFromClipboard() {
			if (!this.activeCell) return;

			let text;
			try {
				text = await navigator.clipboard.readText();
			} catch (e) {
				frappe.show_alert({ message: __("Paste was blocked by the browser"), indicator: "orange" }, 4);
				return;
			}

			const headers = this.headerCells().toArray();
			const lines = text.split(/\r?\n/).filter((line) => line.length);
			const updates = [];

			lines.forEach((line, rowOffset) => {
				const item = this.frm.doc.items[this.activeCell.rowIndex + rowOffset];
				if (!item) return;

				line.split("\t").forEach((value, colOffset) => {
					const col = headers[this.activeCell.colIndex + colOffset];
					const field = col && this.fieldname(col);
					const df = field && this.docfield(field);
					if (!field || !df || df.read_only) return;

					updates.push(frappe.model.set_value(item.doctype, item.name, field, value.trim()));
				});
			});

			await Promise.all(updates);
			this.frm.refresh_field("items");
			this.scheduleRender();
		}
	}

