	// in_list_view - see aimatic/branch_management field-layout work.
	// Anything not listed falls back to a readable default.
	const MIN_WIDTHS = {
		item_code: 140,
		schedule_date: 95,
		qty: 65,
		custom_scheme_qty: 80,
		uom: 60,
		custom_vendor_rate: 95,
		custom_mrp: 85,
		custom_discount_per: 85,
		custom_trade_offer_total: 105,
