	// rates/percentages are deliberately excluded.
	const FOOTER_TOTALS = [
		{ field: "qty", label: "Qty", precision: 0 },
		{ field: "custom_trade_offer_total", label: "Trade Offer", precision: 2 },
		{ field: "amount", label: "Amount", precision: 2 },
