	// and every body-row cell read the *same* value by field position, so
	// there is no way for them to independently drift (no measuring of
	// rendered content, no per-row "max-content" sizing).
	function applyColumnWidths($wrapper) {
		const headerCells = $wrapper.find(".grid-heading-row .data-row").first().children(".col");
		if (!headerCells.length) return;

		const widths = [];
		let total = 0;

		headerCells.each((index, col) => {
			const fieldname = col.dataset.fieldname;
