		const headerCells = $wrapper.find(".grid-heading-row .data-row").first().children(".col").toArray();

		if (footer.children().length !== headerCells.length) {
			footer.empty();
			headerCells.forEach((col, index) => {
				const fieldname = col.dataset.fieldname || "";
