		if (!footer || !footer.length) return;

		const items = Array.isArray(frm.doc.items) ? frm.doc.items : [];

		FOOTER_TOTALS.forEach((total) => {
			const cell = footer.find(`[data-total-field="${total.field}"]`);
			if (!cell.length) return;

			const sum = items.reduce((acc, row) => acc + (flt(row[total.field]) || 0), 0);
