	function addFullscreenToggle($wrapper, frm) {
		const $toolbar = $wrapper.find(".grid-custom-buttons").first();
		if (!$toolbar.length || $toolbar.find(`.${NS}__fullscreen-btn`).length) return;

		const $btn = $(
			`<button type="button" class="btn btn-xs btn-secondary ${NS}__fullscreen-btn" style="margin-left: 4px;">&#x26F6; Full Screen</button>`
		).appendTo($toolbar);

		const setFullscreen = (enable) => {
			$wrapper.toggleClass(`${NS}--fullscreen`, enable);
			$("body").toggleClass(`${NS}--locked`, enable);
			$btn.html(enable ? "&times; Close Full Screen" : "&#x26F6; Full Screen");

			// container dimensions changed - re-lock widths/footer so
			// nothing looks misaligned right after the toggle.
