		const body = $wrapper.find(".grid-body").get(0);
		if (body) {
			new MutationObserver(resync).observe(body, { childList: true, subtree: true, attributes: true, attributeFilter: ["style", "class"] });
		}

		const container = $wrapper.find(".form-grid-container").get(0);
		if (container) {
			container.addEventListener("scroll", () => syncHorizontalScroll($wrapper), { passive: true });
		}
	}

