// ─────────────────────────────────────────────────────────────
// Recalculate all rows (load/refresh)
// ─────────────────────────────────────────────────────────────
function recalculate_all_rows(frm) {
    if (!frm.doc.items || frm.doc.items.length === 0) return;

    var promises = [];

    frm.doc.items.forEach(function(row) {
        if (row.custom_tax_formula) {
            promises.push(
                frappe.db.get_doc('Tax Formula', row.custom_tax_formula).then(function(tf) {
                    row._gst_formula = tf.gst_formula || 'standard';
                    row._adv_formula = tf.advance_tax_formula || 'on_tp';
                    row._has_fed     = tf.has_fed ? 1 : 0;
                })
            );
        }
    });

    Promise.all(promises).then(function() {
        frm.doc.items.forEach(function(row) {
            calculate_row(frm, row.doctype, row.name);
        });
    });
}

// ─────────────────────────────────────────────────────────────
// Single row calculation
// NEVER modifies row.qty
// ─────────────────────────────────────────────────────────────
function calculate_row(frm, cdt, cdn) {
    var row = locals[cdt][cdn];

    // ── Read inputs ──────────────────────────────────────────
    var price        = flt(row.rate);
    var qty          = flt(row.qty);               // NEVER modified
    var discount_per = flt(row.custom_discount_per);
    var trade_offer  = flt(row.custom_trade_offer);
    var mrp          = flt(row.custom_mrp);
    var gst_rate     = flt(row.custom_gst_per);
    var adv_tax_per  = flt(row.custom_advance_tax_per);
    var fed_per      = flt(row.custom_fed_per);
    var is_3rd       = row.custom_is_3rd_schedule ? 1 : 0;

    // ── Read formula from cached Tax Formula doc ─────────────
    var gst_formula = row._gst_formula || 'standard';
    var adv_formula = row._adv_formula || 'on_tp';
    var has_fed     = row._has_fed     || 0;

    // 3rd Schedule override
    if (is_3rd) {
        gst_formula = '3rd_schedule';
    }

    // ── Derived values ───────────────────────────────────────
    var gross_total       = price * qty;
    var discount_value    = (price * discount_per / 100) * qty;
    var trade_offer_total = trade_offer * qty;

    // ── FED ──────────────────────────────────────────────────
    var fed_amount = 0;
    if (has_fed && fed_per) {
        fed_amount = price * qty * (fed_per / 100);
    }

    // ── GST Calculation ──────────────────────────────────────
    var gst_amount = 0;

    if (gst_formula === 'exempted') {
        gst_amount = 0;

    } else if (gst_formula === '3rd_schedule') {
        if (mrp && gst_rate) {
            var retail_price = mrp / ((100 + gst_rate) / 100);
            gst_amount = (retail_price * gst_rate / 100) * qty;
        }

    } else if (gst_formula === 'after_discount_and_to') {
        var unit_taxable = price - (price * discount_per / 100) - trade_offer;
        gst_amount = (unit_taxable * gst_rate / 100) * qty;

    } else if (gst_formula === 'after_discount') {
        var unit_taxable = price - (price * discount_per / 100);
        gst_amount = (unit_taxable * gst_rate / 100) * qty;

    } else if (gst_formula === 'after_to') {
        var unit_taxable = price - trade_offer;
        gst_amount = (unit_taxable * gst_rate / 100) * qty;

    } else {
        // standard
        gst_amount = price * qty * (gst_rate / 100);
    }

    // ── Advance Tax Calculation ──────────────────────────────
    var adv_tax_amount = 0;

    if (adv_tax_per > 0 && adv_formula !== 'exempted') {

        if (adv_formula === 'on_tp_gst_fed_disc_to') {
            var base = gross_total - discount_value + gst_amount + fed_amount - trade_offer_total;
            adv_tax_amount = adv_tax_per * base / 100;

        } else if (adv_formula === 'on_tp_gst_disc_to') {
            var base = gross_total - discount_value + gst_amount - trade_offer_total;
            adv_tax_amount = adv_tax_per * base / 100;

        } else if (adv_formula === 'on_tp_gst_to') {
            var base = gross_total - trade_offer_total + gst_amount;
            adv_tax_amount = adv_tax_per * base / 100;

        } else if (adv_formula === 'on_tp_gst_disc') {
            var base = gross_total - discount_value + gst_amount;
            adv_tax_amount = adv_tax_per * base / 100;

        } else if (adv_formula === 'on_tp_minus_disc') {
            var base = gross_total - discount_value;
            adv_tax_amount = adv_tax_per * base / 100;

        } else {
            // on_tp — standard
            adv_tax_amount = adv_tax_per * gross_total / 100;
        }
    }

    // ── Line Total ───────────────────────────────────────────
    var line_total = gross_total - discount_value + gst_amount + adv_tax_amount - trade_offer_total + fed_amount;

    // ── Price Without Taxes (Inventory Rate) ─────────────────
    // Gross - Discount - Trade Offer + FED (FED is part of cost)
    // Excludes GST and Advance Tax (recoverable)
    var price_without_taxes = qty > 0 ? (gross_total - discount_value - trade_offer_total + fed_amount) / qty : 0;

    // ── Price After Taxes (Landed Cost) ──────────────────────
    var price_after_taxes = qty > 0 ? line_total / qty : 0;

    // ── Write calculated fields ──────────────────────────────
    // row.qty is NEVER set here
    frappe.model.set_value(cdt, cdn, 'custom_gross_total',         flt(gross_total, 2));
    frappe.model.set_value(cdt, cdn, 'custom_discount_amnt',       flt(discount_value, 2));
    frappe.model.set_value(cdt, cdn, 'custom_trade_offer_total',   flt(trade_offer_total, 2));
    frappe.model.set_value(cdt, cdn, 'custom_gst_amount',          flt(gst_amount, 2));
    frappe.model.set_value(cdt, cdn, 'custom_advance_tax_amount',  flt(adv_tax_amount, 2));
    frappe.model.set_value(cdt, cdn, 'custom_fed_amount',          flt(fed_amount, 2));
    frappe.model.set_value(cdt, cdn, 'custom_line_total',          flt(line_total, 2));
    frappe.model.set_value(cdt, cdn, 'custom_price_without_taxes', flt(price_without_taxes, 4));
    frappe.model.set_value(cdt, cdn, 'custom_price_after_taxes',   flt(price_after_taxes, 4));
    frappe.model.set_value(cdt, cdn, 'amount',                     flt(line_total, 2));

    update_invoice_totals(frm);
}

// ─────────────────────────────────────────────────────────────
// Update invoice header totals
