    });
}

// ─────────────────────────────────────────────────────────────
// Single row calculation — NEVER modifies row.qty
// ─────────────────────────────────────────────────────────────
function calculate_row(frm, cdt, cdn) {
    var row = locals[cdt][cdn];

    var price        = flt(row.rate);
    var qty          = flt(row.qty);                    // paid qty — never changed
    var scheme_qty   = flt(row.custom_scheme_qty);
    var trade_offer  = flt(row.custom_trade_offer);
    var mrp          = flt(row.custom_mrp);
    var gst_rate     = flt(row.custom_gst_per);
    var adv_tax_per  = flt(row.custom_advance_tax_per);
    var fed_per      = flt(row.custom_fed_per);
    var discount_per = flt(row.discount_percentage);
    var formula      = (row.custom_tax_formula || '').toLowerCase().trim();

    // ── Derived quantities ───────────────────────────────────
    var effective_qty = qty - scheme_qty;
    if (effective_qty < 0) effective_qty = 0;

    var inventory_qty = qty + scheme_qty;  // total stock units

    // ── Derived values ───────────────────────────────────────
    var gross_total       = price * effective_qty;
    var discount_value    = (price * discount_per / 100) * effective_qty;
    var trade_offer_total = trade_offer * effective_qty;
    var fed_amount        = price * effective_qty * (fed_per / 100);

    // ── GST Calculation ──────────────────────────────────────
    var gst_amount       = 0;
    var gst_3rd_schedule = 0;

    if (formula.indexOf('exempted') >= 0 || formula.indexOf('gst exempt') >= 0) {
        gst_amount = 0;

    } else if (formula.indexOf('3rd schedule') >= 0 || formula.indexOf('third schedule') >= 0) {
        gst_amount       = ((mrp / ((100 + gst_rate) / 100)) * (gst_rate / 100)) * effective_qty;
        gst_3rd_schedule = gst_amount;

    } else if (formula.indexOf('discount') >= 0 && formula.indexOf('trade offer') >= 0 && formula.indexOf('including scheme') >= 0) {
        gst_amount = ((price * qty - price * effective_qty * discount_per / 100 - trade_offer * qty) * gst_rate) / 100;

    } else if (formula.indexOf('discount') >= 0 && formula.indexOf('trade offer') >= 0) {
        gst_amount = ((price - (price * discount_per / 100) - trade_offer) * (gst_rate / 100)) * effective_qty;

    } else if (formula.indexOf('discount') >= 0 && formula.indexOf('trade offer') < 0) {
        gst_amount = ((price - (price * discount_per / 100)) * (gst_rate / 100)) * effective_qty;

    } else if (formula.indexOf('trade offer') >= 0 && formula.indexOf('discount') < 0) {
        gst_amount = ((price - trade_offer) * (gst_rate / 100)) * effective_qty;

    } else if (formula.indexOf('with scheme') >= 0 || formula.indexOf('including scheme') >= 0) {
        gst_amount = price * qty * (gst_rate / 100);

    } else {
        // Standard without scheme
        gst_amount = price * effective_qty * (gst_rate / 100);
    }

    // ── Advance Tax Calculation ──────────────────────────────
    var adv_tax_amount = 0;

    if (adv_tax_per > 0 && formula.indexOf('adv exempt') < 0 && formula.indexOf('advance tax exempt') < 0) {

        if (formula.indexOf('fed') >= 0 && formula.indexOf('discount') >= 0 && formula.indexOf('trade offer') >= 0) {
            adv_tax_amount = adv_tax_per * (gross_total - discount_value + gst_amount + fed_amount - trade_offer_total) / 100;

        } else if (formula.indexOf('discount') >= 0 && formula.indexOf('trade offer') >= 0) {
            adv_tax_amount = adv_tax_per * (gross_total - discount_value + gst_amount - trade_offer_total) / 100;

        } else if (formula.indexOf('trade offer') >= 0 && formula.indexOf('discount') < 0) {
            adv_tax_amount = adv_tax_per * (gross_total - trade_offer_total + gst_amount) / 100;

        } else if (formula.indexOf('gst') >= 0 && formula.indexOf('discount') >= 0) {
            adv_tax_amount = adv_tax_per * (gross_total - discount_value + gst_amount) / 100;

        } else if (formula.indexOf('discount') >= 0) {
            adv_tax_amount = adv_tax_per * (gross_total - discount_value) / 100;

        } else {
            adv_tax_amount = adv_tax_per * gross_total / 100;
        }
    }

    // ── Line Total ───────────────────────────────────────────
    var line_total = gross_total - discount_value + gst_amount + adv_tax_amount - trade_offer_total + fed_amount;

    // ── Valuation Rate (landed cost per unit across all stock units) ──
    var valuation_rate  = (inventory_qty > 0) ? (line_total / inventory_qty) : 0;

    // ── Base Cost Price per unit ─────────────────────────────
    var base_cost_price = price - (price * discount_per / 100) - trade_offer + (qty > 0 ? fed_amount / qty : 0);

    // ── Write calculated fields — row.qty NEVER touched ──────
    frappe.model.set_value(cdt, cdn, 'custom_gross_total',        flt(gross_total, 2));
    frappe.model.set_value(cdt, cdn, 'custom_trade_offer_total',  flt(trade_offer_total, 2));
    frappe.model.set_value(cdt, cdn, 'custom_gst_amount',         flt(gst_amount, 2));
    frappe.model.set_value(cdt, cdn, 'custom_gst_3rd_schedule',   flt(gst_3rd_schedule, 2));
    frappe.model.set_value(cdt, cdn, 'custom_advance_tax_amount', flt(adv_tax_amount, 2));
    frappe.model.set_value(cdt, cdn, 'custom_fed_amount',         flt(fed_amount, 2));
    frappe.model.set_value(cdt, cdn, 'custom_line_total',         flt(line_total, 2));
    frappe.model.set_value(cdt, cdn, 'custom_base_cost_price',    flt(base_cost_price, 4));
    frappe.model.set_value(cdt, cdn, 'custom_inventory_qty',      flt(inventory_qty, 3));
    frappe.model.set_value(cdt, cdn, 'amount',                    flt(line_total, 2));
    // row.qty is NEVER set here

    update_invoice_totals(frm);
}

// ─────────────────────────────────────────────────────────────
// Update invoice header totals
// ─────────────────────────────────────────────────────────────
function update_invoice_totals(frm) {
    var total_qty     = 0;
    var total_gross   = 0;
    var total_gst     = 0;
    var total_adv_tax = 0;
    var total_fed     = 0;
    var total_trade   = 0;
    var total_line    = 0;

    (frm.doc.items || []).forEach(function(row) {
        total_qty     += flt(row.qty) + flt(row.custom_scheme_qty);
        total_gross   += flt(row.custom_gross_total);
        total_gst     += flt(row.custom_gst_amount);
        total_adv_tax += flt(row.custom_advance_tax_amount);
        total_fed     += flt(row.custom_fed_amount);
        total_trade   += flt(row.custom_trade_offer_total);
        total_line    += flt(row.custom_line_total);
    });

    // ── Custom summary fields ────────────────────────────────
    if (frm.fields_dict['custom_total_gross'])
        frm.set_value('custom_total_gross',       flt(total_gross, 2));
    if (frm.fields_dict['custom_total_gst'])
        frm.set_value('custom_total_gst',         flt(total_gst, 2));
    if (frm.fields_dict['custom_total_advance_tax'])
        frm.set_value('custom_total_advance_tax', flt(total_adv_tax, 2));
    if (frm.fields_dict['custom_total_fed'])
        frm.set_value('custom_total_fed',         flt(total_fed, 2));
    if (frm.fields_dict['custom_grand_line_total'])
        frm.set_value('custom_grand_line_total',  flt(total_line, 2));

    // ── Core ERPNext invoice fields ──────────────────────────
    frm.set_value('total_qty',        flt(total_qty, 3));
    frm.set_value('total',            flt(total_line, 2));
    frm.set_value('net_total',        flt(total_line, 2));
    frm.set_value('base_total',       flt(total_line, 2));
    frm.set_value('base_net_total',   flt(total_line, 2));
    frm.set_value('grand_total',      flt(total_line, 2));
    frm.set_value('base_grand_total', flt(total_line, 2));
    frm.set_value('rounded_total',    flt(Math.round(total_line), 2));

    frm.refresh_fields();
}

// ============================================================
// PURCHASE ORDER CLIENT SCRIPT
// ERPNext v16
//
// custom_vendor_rate = actual editable vendor price
// price_list_rate     = ERPNext fetched buying price, fallback only
// rate                = calculated net inventory unit cost
//
// GST and Advance Tax are previews only on Purchase Order.
// ============================================================

(() => {
    const formulaCache = {};

    let calculationRunning = false;
    let calculationQueued = false;
    let calculationTimer = null;

    function flt4(value) {
        return Math.round(flt(value || 0) * 10000) / 10000;
    }

    function different(value1, value2) {
        return Math.abs(
            flt(value1 || 0) - flt(value2 || 0)
        ) > 0.00005;
    }

    // ========================================================
    // ARITHMETIC PARSER
    // Supports + - * / and parentheses
    // ========================================================

    function evaluateArithmetic(expression) {
        const input = String(expression || "")
            .replace(/\s+/g, "");

        if (!input) {
            return 0;
        }

        let position = 0;

        function peek() {
            return input[position] || "";
        }

        function consume() {
            const value = input[position] || "";
            position = position + 1;
            return value;
        }

        function parseNumber() {
            let text = "";
            let decimalCount = 0;

            while (position < input.length) {
                const character = peek();

                if (
                    character >= "0" &&
                    character <= "9"
                ) {
                    text = text + consume();
                } else if (character === ".") {
                    decimalCount = decimalCount + 1;

                    if (decimalCount > 1) {
                        throw new Error(
                            "Invalid decimal number"
                        );
                    }

                    text = text + consume();
                } else {
                    break;
                }
            }

            if (!text || text === ".") {
                throw new Error(
                    `Invalid number at position ${position}`
                );
            }

            const value = Number(text);

            if (!Number.isFinite(value)) {
                throw new Error("Invalid numeric value");
            }

            return value;
        }

        function parseFactor() {
            if (peek() === "+") {
                consume();
                return parseFactor();
            }

            if (peek() === "-") {
                consume();
                return -parseFactor();
            }

            if (peek() === "(") {
                consume();

                const value = parseExpression();

                if (peek() !== ")") {
                    throw new Error(
                        "Missing closing parenthesis"
                    );
                }

                consume();

                return value;
            }

            return parseNumber();
        }

        function parseTerm() {
            let value = parseFactor();

            while (
                peek() === "*" ||
                peek() === "/"
            ) {
                const operator = consume();
                const rightValue = parseFactor();

                if (operator === "*") {
                    value = value * rightValue;
                } else {
                    if (rightValue === 0) {
                        throw new Error("Division by zero");
                    }

                    value = value / rightValue;
                }
            }

            return value;
        }

        function parseExpression() {
            let value = parseTerm();

            while (
                peek() === "+" ||
                peek() === "-"
            ) {
                const operator = consume();
                const rightValue = parseTerm();

                if (operator === "+") {
                    value = value + rightValue;
                } else {
                    value = value - rightValue;
                }
            }

            return value;
        }

        const result = parseExpression();

        if (position !== input.length) {
            throw new Error(
                `Unexpected character at position ${position}`
            );
        }

        return result;
    }

    function replaceVariables(expression, namespace) {
        let result = String(expression || "");

        Object.keys(namespace)
            .sort((first, second) => {
                return second.length - first.length;
            })
            .forEach(variableName => {
                const escapedName = variableName.replace(
                    /[.*+?^${}()|[\]\\]/g,
                    "\\$&"
                );

                result = result.replace(
                    new RegExp(
                        `\\b${escapedName}\\b`,
                        "g"
                    ),
                    String(
                        flt(namespace[variableName] || 0)
                    )
                );
            });

        if (/[A-Za-z_]/.test(result)) {
            throw new Error(
                `Unknown variable in formula: ${result}`
            );
        }

        return result;
    }

    async function getFormula(formulaName) {
        if (!formulaName) {
            return null;
        }

        if (formulaCache[formulaName]) {
            return formulaCache[formulaName];
        }

        const response = await frappe.db.get_value(
            "Tax Formula",
            formulaName,
            [
                "formula_string",
                "formula_type"
            ]
        );

        const formula = response.message || {};

        formulaCache[formulaName] = formula;

        return formula;
    }

    async function calculateFormula(
        formulaName,
        namespace
    ) {
        if (!formulaName) {
            return 0;
        }

        const formula = await getFormula(formulaName);
        const formulaString =
            formula && formula.formula_string
                ? formula.formula_string
                : "";

        if (!formulaString) {
            return 0;
        }

        const expression = replaceVariables(
            formulaString,
            namespace
        );

        return flt4(
            evaluateArithmetic(expression)
        );
    }

    // ========================================================
    // VENDOR RATE INITIALIZATION
    //
    // Important:
    // custom_vendor_rate is initialized only when blank.
    // Existing/user-edited values are never replaced using
    // price_list_rate.
    // ========================================================

    async function initializeVendorRate(cdt, cdn) {
        const row = locals[cdt][cdn];

        if (!row) {
            return;
        }

        // Existing saved or manually entered vendor rate wins.
        if (flt(row.custom_vendor_rate) > 0) {
            return;
        }

        const fetchedRate = flt(
            row.price_list_rate ||
            row.rate ||
            0
        );

        if (fetchedRate > 0) {
            await frappe.model.set_value(
                cdt,
                cdn,
                "custom_vendor_rate",
                flt4(fetchedRate)
            );
        }
    }

    // ========================================================
    // THIRD SCHEDULE
    // ========================================================

    async function applyThirdScheduleFormula(cdt, cdn) {
        const row = locals[cdt][cdn];

        if (
            !row ||
            !cint(row.custom_is_3rd_schedule)
        ) {
            return;
        }

        const existingFormula = String(
            row.custom_gst_formula || ""
        ).toLowerCase();

        if (existingFormula.startsWith("3rd")) {
            return;
        }

        const records = await frappe.db.get_list(
            "Tax Formula",
            {
                filters: {
                    formula_type: "gst"
                },
                fields: [
                    "name",
                    "formula_name"
                ],
                limit: 100
            }
        );

        const matchingFormula = (
            records || []
        ).find(record => {
            const name = String(
                record.formula_name ||
                record.name ||
                ""
            ).toLowerCase();

            return name.includes("3rd schedule");
        });

        if (matchingFormula) {
            await frappe.model.set_value(
                cdt,
                cdn,
                "custom_gst_formula",
                matchingFormula.name
            );
        }
    }

    // ========================================================
    // UPDATE ROW WITHOUT UNNECESSARY EVENT LOOPS
    // ========================================================

    async function setRowValues(cdt, cdn, values) {
        const row = locals[cdt][cdn];

        for (
            const [fieldname, value]
            of Object.entries(values)
        ) {
            if (
                different(
                    row[fieldname],
                    value
                )
            ) {
                await frappe.model.set_value(
                    cdt,
                    cdn,
                    fieldname,
                    value
                );
            }
        }
    }

    // ========================================================
    // CALCULATE ONE ROW
    // ========================================================

    async function calculateRow(frm, cdt, cdn) {
        let row = locals[cdt][cdn];

        if (!row || !row.item_code) {
            return;
        }

        await initializeVendorRate(cdt, cdn);
        await applyThirdScheduleFormula(cdt, cdn);

        row = locals[cdt][cdn];

        // custom_vendor_rate always has priority.
        const vendorRate = flt(
            row.custom_vendor_rate || 0
        );

        const qty = flt(row.qty || 0);
        const schemeQty = flt(
            row.custom_scheme_qty || 0
        );
        const discountPer = flt(
            row.custom_discount_per || 0
        );
        const tradeOfferTotal = flt(
            row.custom_trade_offer_total || 0
        );
        const mrp = flt(
            row.custom_mrp || 0
        );
        const gstPer = flt(
            row.custom_gst_per || 0
        );
        const advanceTaxPer = flt(
            row.custom_advance_tax_per || 0
        );
        const fedPer = flt(
            row.custom_fed_per || 0
        );

        if (schemeQty < 0) {
            throw new Error(
                `Scheme quantity cannot be negative for ${row.item_code}`
            );
        }

        if (schemeQty > qty) {
            throw new Error(
                `Scheme quantity cannot exceed quantity for ${row.item_code}`
            );
        }

        if (
            discountPer < 0 ||
            discountPer > 100
        ) {
            throw new Error(
                `Discount must be between 0 and 100 for ${row.item_code}`
            );
        }

        const paidQty = qty - schemeQty;

        const grossTotal =
            vendorRate * qty;

        const discountAmount =
            vendorRate *
            discountPer /
            100 *
            paidQty;

        const tradeOffer =
            paidQty ?
            tradeOfferTotal / paidQty : 0;

        const namespace = {
            rate: vendorRate,
            qty: qty,
            custom_scheme_qty: schemeQty,
            custom_discount_per: discountPer,
            custom_trade_offer: tradeOffer,
            custom_mrp: mrp,
            custom_gst_per: gstPer,
            custom_advance_tax_per:
                advanceTaxPer,
            custom_fed_per: fedPer,
            custom_gross_total:
                grossTotal,
            custom_discount_amnt:
                discountAmount,
            custom_trade_offer_total:
                tradeOfferTotal,
            custom_gst_amount: 0,
            custom_advance_tax_amount: 0,
            custom_fed_amount: 0
        };

        let fedAmount = 0;

        if (row.custom_fed_formula) {
            fedAmount = await calculateFormula(
                row.custom_fed_formula,
                namespace
            );
        } else if (fedPer) {
            fedAmount =
                vendorRate *
                paidQty *
                fedPer /
                100;
        }

        fedAmount = flt4(fedAmount);

        namespace.custom_fed_amount =
            fedAmount;

        const gstAmount = flt4(
            await calculateFormula(
                row.custom_gst_formula,
                namespace
            )
        );

        namespace.custom_gst_amount =
            gstAmount;

        const advanceTaxAmount = flt4(
            await calculateFormula(
                row.custom_advance_tax_formula,
                namespace
            )
        );

        const inventoryAmount =
            grossTotal -
            discountAmount -
            tradeOfferTotal +
            fedAmount;

        const netUnitCost = qty
            ? inventoryAmount / qty
            : 0;

        const lineTotal =
            inventoryAmount +
            gstAmount +
            advanceTaxAmount;

        /*
         * Do not set price_list_rate here.
         *
         * ERPNext may have fetched an old Item Price, but it
         * must not replace custom_vendor_rate. Your On Submit
         * server script will update Item Price using the final
         * custom_vendor_rate.
         */

        await setRowValues(
            cdt,
            cdn,
            {
                custom_gross_total:
                    flt4(grossTotal),

                custom_discount_amnt:
                    flt4(discountAmount),

                custom_trade_offer_total:
                    flt4(tradeOfferTotal),

                custom_trade_offer:
                    flt4(tradeOffer),

                custom_fed_amount:
                    flt4(fedAmount),

                custom_gst_amount:
                    flt4(gstAmount),

                custom_advance_tax_amount:
                    flt4(advanceTaxAmount),

                custom_price_without_taxes:
                    flt4(netUnitCost),

                custom_price_after_taxes:
                    flt4(
                        qty
                            ? lineTotal / qty
                            : 0
                    ),

                custom_line_total:
                    flt4(lineTotal),

                // ERPNext stock/inventory rate
                rate:
                    flt4(netUnitCost),

                // Custom discount is already included
                discount_percentage: 0,
                discount_amount: 0,
                distributed_discount_amount: 0
            }
        );

        console.log(
            "PO custom calculation",
            {
                item_code: row.item_code,
                vendor_rate: vendorRate,
                price_list_rate:
                    row.price_list_rate,
                qty: qty,
                gross: grossTotal,
                discount: discountAmount,
                trade_offer:
                    tradeOfferTotal,
                fed: fedAmount,
                gst: gstAmount,
                advance_tax:
                    advanceTaxAmount,
                inventory_rate:
                    netUnitCost,
                line_total: lineTotal
            }
        );
    }

    // ========================================================
    // CUSTOM DOCUMENT TOTALS
    // ========================================================

    async function updateCustomTotals(frm) {
        const totals = (
            frm.doc.items || []
        ).reduce(
            (result, row) => {
                result.gross =
                    result.gross +
                    flt(
                        row.custom_gross_total
                    );

                result.discount =
                    result.discount +
                    flt(
                        row.custom_discount_amnt
                    );

                result.trade =
                    result.trade +
                    flt(
                        row.custom_trade_offer_total
                    );

                result.fed =
                    result.fed +
                    flt(
                        row.custom_fed_amount
                    );

                result.gst =
                    result.gst +
                    flt(
                        row.custom_gst_amount
                    );

                result.advance =
                    result.advance +
                    flt(
                        row.custom_advance_tax_amount
                    );

                result.grand =
                    result.grand +
                    flt(
                        row.custom_line_total
                    );

                return result;
            },
            {
                gross: 0,
                discount: 0,
                trade: 0,
                fed: 0,
                gst: 0,
                advance: 0,
                grand: 0
            }
        );

        const values = {
            custom_total_gross:
                flt4(totals.gross),

            custom_total_discount:
                flt4(totals.discount),

            custom_total_trade_offer:
                flt4(totals.trade),

            custom_total_fed:
                flt4(totals.fed),

            custom_total_gst:
                flt4(totals.gst),

            custom_total_advance_tax:
                flt4(totals.advance),

            custom_grand_line_total:
                flt4(totals.grand)
        };

        for (
            const [fieldname, value]
            of Object.entries(values)
        ) {
            if (
                different(
                    frm.doc[fieldname],
                    value
                )
            ) {
                await frm.set_value(
                    fieldname,
                    value
                );
            }
        }
    }

    // ========================================================
    // CALCULATE DOCUMENT
    // ========================================================

    async function calculateDocument(frm) {
        if (frm.doc.docstatus !== 0) {
            return;
        }

        if (calculationRunning) {
            calculationQueued = true;
            return;
        }

        calculationRunning = true;
        calculationQueued = false;

        try {
            if (!frm.doc.ignore_pricing_rule) {
                await frm.set_value(
                    "ignore_pricing_rule",
                    1
                );
            }

            for (
                const row of frm.doc.items || []
            ) {
                await calculateRow(
                    frm,
                    row.doctype,
                    row.name
                );
            }

            await updateCustomTotals(frm);

            frm.refresh_field("items");
            frm.refresh_fields();

        } catch (error) {
            console.error(
                "Purchase Order calculation failed",
                error
            );

            frappe.msgprint({
                title: __(
                    "Purchase Order Calculation Error"
                ),
                indicator: "red",
                message:
                    frappe.utils.escape_html(
                        error.message ||
                        String(error)
                    )
            });
        } finally {
            calculationRunning = false;

            if (calculationQueued) {
                calculationQueued = false;
                scheduleCalculation(frm, 300);
            }
        }
    }

    function scheduleCalculation(
        frm,
        delay = 250
    ) {
        clearTimeout(calculationTimer);

        calculationTimer = setTimeout(
            function () {
                calculateDocument(frm);
            },
            delay
        );
    }

    // ========================================================
    // LIVE CALCULATION DIALOG
    // ========================================================

    function showCalculationPreview(frm) {
        const currency =
            frm.doc.currency || "PKR";

        const rows = (
            frm.doc.items || []
        ).map(row => {
            return `
                <tr>
                    <td>${frappe.utils.escape_html(
                        row.item_code || ""
                    )}</td>
                    <td class="text-right">
                        ${format_currency(
                            row.custom_vendor_rate,
                            currency
                        )}
                    </td>
                    <td class="text-right">
                        ${flt(row.qty)}
                    </td>
                    <td class="text-right">
                        ${format_currency(
                            row.custom_gross_total,
                            currency
                        )}
                    </td>
                    <td class="text-right">
                        ${format_currency(
                            row.custom_discount_amnt,
                            currency
                        )}
                    </td>
                    <td class="text-right">
                        ${format_currency(
                            row.custom_trade_offer_total,
                            currency
                        )}
                    </td>
                    <td class="text-right">
                        ${format_currency(
                            row.custom_fed_amount,
                            currency
                        )}
                    </td>
                    <td class="text-right">
                        ${format_currency(
                            row.custom_price_without_taxes,
                            currency
                        )}
                    </td>
                    <td class="text-right">
                        ${format_currency(
                            row.custom_gst_amount,
                            currency
                        )}
                    </td>
                    <td class="text-right">
                        ${format_currency(
                            row.custom_advance_tax_amount,
                            currency
                        )}
                    </td>
                    <td class="text-right">
                        ${format_currency(
                            row.custom_line_total,
                            currency
                        )}
                    </td>
                </tr>
            `;
        }).join("");

        frappe.msgprint({
            title: __(
                "Live Purchase Order Calculation"
            ),
            indicator: "blue",
            wide: true,
            message: `
                <div style="overflow:auto">
                    <table class="table table-bordered">
                        <thead>
                            <tr>
                                <th>Item</th>
                                <th>Vendor Rate</th>
                                <th>Qty</th>
                                <th>Gross</th>
                                <th>Discount</th>
                                <th>Trade Offer</th>
                                <th>FED</th>
                                <th>Inventory Rate</th>
                                <th>GST Preview</th>
                                <th>Advance Tax</th>
                                <th>Expected Invoice Total</th>
                            </tr>
                        </thead>
                        <tbody>
                            ${rows}
                        </tbody>
                    </table>
                </div>

                <hr>

                <b>Total Gross:</b>
                ${format_currency(
                    frm.doc.custom_total_gross,
                    currency
                )}<br>

                <b>Total Discount:</b>
                ${format_currency(
                    frm.doc.custom_total_discount,
                    currency
                )}<br>

                <b>Total Trade Offer:</b>
                ${format_currency(
                    frm.doc.custom_total_trade_offer,
                    currency
                )}<br>

                <b>Total FED:</b>
                ${format_currency(
                    frm.doc.custom_total_fed,
                    currency
                )}<br>

                <b>GST Preview:</b>
                ${format_currency(
                    frm.doc.custom_total_gst,
                    currency
                )}<br>

                <b>Advance Tax Preview:</b>
                ${format_currency(
                    frm.doc.custom_total_advance_tax,
                    currency
                )}<br>

                <b>Expected Invoice Total:</b>
                ${format_currency(
                    frm.doc.custom_grand_line_total,
                    currency
                )}
            `
        });
    }

    // ========================================================
    // PURCHASE ORDER EVENTS
    // ========================================================

    frappe.ui.form.on(
        "Purchase Order",
        {
            setup(frm) {
                frm.set_query(
                    "custom_gst_formula",
                    "items",
                    function () {
                        return {
                            filters: {
                                formula_type: "gst"
                            }
                        };
                    }
                );

                frm.set_query(
                    "custom_advance_tax_formula",
                    "items",
                    function () {
                        return {
                            filters: {
                                formula_type:
                                    "advance_tax"
                            }
                        };
                    }
                );

                frm.set_query(
                    "custom_fed_formula",
                    "items",
                    function () {
                        return {
                            filters: {
                                formula_type: "fed"
                            }
                        };
                    }
                );
            },

            onload(frm) {
                scheduleCalculation(frm, 1000);
            },

            onload_post_render(frm) {
                scheduleCalculation(frm, 1200);
            },

            refresh(frm) {
                if (frm.doc.docstatus !== 0) {
                    return;
                }

                frm.remove_custom_button(
                    __("Recalculate Custom Costs"),
                    __("Custom Calculation")
                );

                frm.remove_custom_button(
                    __("Show Live Calculation"),
                    __("Custom Calculation")
                );

                frm.add_custom_button(
                    __("Recalculate Custom Costs"),
                    async function () {
                        await calculateDocument(frm);

                        frappe.show_alert({
                            message: __(
                                "Purchase Order values recalculated"
                            ),
                            indicator: "green"
                        });
                    },
                    __("Custom Calculation")
                );

                frm.add_custom_button(
                    __("Show Live Calculation"),
                    async function () {
                        await calculateDocument(frm);
                        showCalculationPreview(frm);
                    },
                    __("Custom Calculation")
                );

                scheduleCalculation(frm, 600);
            },

            validate(frm) {
                return calculateDocument(frm);
            },

            items_add(frm) {
                scheduleCalculation(frm, 500);
            },

            items_remove(frm) {
                scheduleCalculation(frm, 300);
            },

            supplier(frm) {
                scheduleCalculation(frm, 1200);
            }
        }
    );

