    // PURCHASE ORDER ITEM EVENTS
    // ========================================================

    frappe.ui.form.on(
        "Purchase Order Item",
        {
            item_code(frm, cdt, cdn) {
                /*
                 * ERPNext fetches Item Price asynchronously.
                 * Wait until that finishes, then initialize
                 * custom_vendor_rate only when it is blank.
                 */
                setTimeout(
                    async function () {
                        await initializeVendorRate(
                            cdt,
                            cdn
                        );

                        scheduleCalculation(
                            frm,
                            100
                        );
                    },
                    1000
                );
            },

