            purchase_order_item(frm) {
                scheduleCalculation(frm, 1000);
            },

            /*
             * ERPNext can reset rate/price_list_rate after
             * item or quantity processing. Run our calculation
             * again, but never copy those fields into an existing
             * custom_vendor_rate.
             */

            price_list_rate(frm, cdt, cdn) {
                const row = locals[cdt][cdn];

                if (
                    !calculationRunning &&
                    !flt(row.custom_vendor_rate)
                ) {
                    setTimeout(
