    onload_post_render(frm) {
        // Grid DOM exists after first render; defer setup to ensure stability
        setTimeout(() => setup_items_excel_grid(frm), 200);
    },

    refresh(frm) {
        // Grid is rebuilt on refresh, so re-apply enhancements
        setTimeout(() => setup_items_excel_grid(frm), 200);
    },
});

// ============================================================================
// Main Setup
// ============================================================================

/**
 * Initialize Excel-like grid enhancements
 * Applies styling, toolbar, sticky columns, and event handlers
 * 
 * @param {Frappe.ui.Form} frm - Frappe form instance
 */
function setup_items_excel_grid(frm) {
    const grid = frm.fields_dict.items?.grid;

    if (!grid || !grid.wrapper) {
        console.warn("[ExcelGrid] Grid wrapper not found");
        return;
    }

    // Inject CSS only once per page load
    inject_items_excel_css();
    inject_items_grid_overlap_fix_css();

    const $wrapper = $(grid.wrapper);
    $wrapper.addClass("excel-items-grid");

    // Create toolbar (only once)
    if (!$wrapper.children(".excel-grid-toolbar").length) {
        create_toolbar($wrapper);
    }

    // Update grid metadata and styling
    update_items_grid_count(frm, $wrapper);
    mark_items_grid_sticky_columns($wrapper);
    queue_items_grid_header_sync($wrapper);

    // Attach event handlers
    attach_toolbar_events($wrapper);
    attach_grid_change_events(frm, $wrapper);
    attach_keyboard_events($wrapper);
}

/**
 * Create and insert toolbar UI
 * 
 * @param {jQuery} $wrapper - Grid wrapper element
 */
function create_toolbar($wrapper) {
    const $toolbar = $(`
        <div class="excel-grid-toolbar" role="toolbar" aria-label="Spreadsheet controls">
            <div class="excel-grid-toolbar-left">
                <strong id="excel-grid-title">Items Spreadsheet</strong>
                <span 
                    class="excel-grid-row-count" 
                    id="excel-grid-row-count" 
                    aria-live="polite" 
                    aria-label="Number of rows"
                >
                    0 rows
                </span>
                <span class="excel-grid-help" aria-hidden="true">
                    Press <kbd>Escape</kbd> to close full screen
                </span>
            </div>

            <button
                type="button"
                class="btn btn-primary btn-sm excel-grid-toggle"
                id="excel-grid-fullscreen-btn"
                aria-pressed="false"
                aria-label="Toggle full-screen mode"
                title="Expand grid to full screen (Esc to exit)"
            >
                <span class="icon">⛶</span>
                <span class="label">Full Screen</span>
            </button>
        </div>
    `);

    $wrapper.prepend($toolbar);
}

/**
 * Attach toolbar button event handlers
 * 
 * @param {jQuery} $wrapper - Grid wrapper element
 */
function attach_toolbar_events($wrapper) {
    const $toggle_button = $wrapper.find("> .excel-grid-toolbar .excel-grid-toggle");

    $toggle_button
        .off("click.excelItemsGrid")
        .on("click.excelItemsGrid", function (event) {
            event.preventDefault();
            event.stopPropagation();

            const enable = !$wrapper.hasClass("excel-items-grid-fullscreen");
            set_items_grid_fullscreen($wrapper, enable);
        });
}

/**
 * Attach grid change event handlers
 * Runs sticky marking immediately in RAF; debounces expensive header sync
 * 
 * @param {Frappe.ui.Form} frm - Frappe form instance
 * @param {jQuery} $wrapper - Grid wrapper element
 */
function attach_grid_change_events(frm, $wrapper) {
    const debounced_header_sync = excel_grid_debounce(() => {
        queue_items_grid_header_sync($wrapper);
    }, 180);

    $wrapper
        .off("change.excelItemsGrid")
        .on("change.excelItemsGrid", function () {
            // Fast operations in RAF
            requestAnimationFrame(() => {
                mark_items_grid_sticky_columns($wrapper);
                update_items_grid_count(frm, $wrapper);
            });
            // Expensive header measurement debounced
            debounced_header_sync();
        });

    // Allow scrolling area to receive keyboard focus
    $wrapper.find(".form-grid-container")
        .attr("tabindex", "0")
        .attr("role", "region")
        .attr("aria-label", "Scrollable spreadsheet grid");
}

/**
 * Attach keyboard event handlers
 * Supports Escape to exit full-screen, arrow keys for navigation
 * 
 * @param {jQuery} $wrapper - Grid wrapper element
 */
function attach_keyboard_events($wrapper) {
    $(document)
        .off("keydown.excelItemsGrid")
        .on("keydown.excelItemsGrid", function (event) {
            // Escape: close full-screen mode if open (but not if a dialog is open)
            if (
                event.key === "Escape" &&
                $(".excel-items-grid-fullscreen").length &&
                !$(".modal.show").length
            ) {
                event.preventDefault();

                const $open_grid = $(".excel-items-grid-fullscreen").first();
                set_items_grid_fullscreen($open_grid, false);
            }
        });
}

// ============================================================================
// Grid State Management
// ============================================================================

/**
 * Update row count display
 * 
 * @param {Frappe.ui.Form} frm - Frappe form instance
 * @param {jQuery} $wrapper - Grid wrapper element
 */
function update_items_grid_count(frm, $wrapper) {
    const row_count = Array.isArray(frm.doc.items) ? frm.doc.items.length : 0;
    const label = row_count === 1 ? "row" : "rows";

    $wrapper
        .find("> .excel-grid-toolbar .excel-grid-row-count")
        .text(`${row_count} ${label}`)
        .attr("aria-label", `${row_count} ${label}`);
}

/**
 * Mark sticky columns with appropriate classes
 * Left: checkbox, index, item_code
 * Right: edit button
 * 
 * @param {jQuery} $wrapper - Grid wrapper element
 */
function mark_items_grid_sticky_columns($wrapper) {
    // Remove all sticky classes (refresh on each update)
    $wrapper
        .find(
            ".excel-sticky-check, " +
            ".excel-sticky-index, " +
            ".excel-sticky-item, " +
            ".excel-sticky-right"
        )
        .removeClass(
            "excel-sticky-check excel-sticky-index excel-sticky-item excel-sticky-right"
        );

    // Left: Checkbox column
    $wrapper
        .find(".data-row > .row-check")
        .addClass("excel-sticky-check");

    // Left: Row number column
    $wrapper
        .find(".data-row > .row-index")
        .addClass("excel-sticky-index");

    // Left: Item Code (frozen like Excel's first important column)
    $wrapper
        .find('.data-row > [data-fieldname="item_code"]')
        .addClass("excel-sticky-item");

    // Right: Edit button (keep visible on every row)
    $wrapper.find(".btn-open-row").each(function () {
        $(this).closest(".col").addClass("excel-sticky-right");
    });

    // Right: Settings/gear column (keep visible in header)
    $wrapper
        .find(".grid-heading-row .data-row")
        .each(function () {
            $(this).children(".col").last().addClass("excel-sticky-right");
        });
}

/**
 * Toggle full-screen mode
 * Closes any other open grids first
 * 
 * @param {jQuery} $wrapper - Grid wrapper element
 * @param {boolean} enable - Enable or disable full-screen
 */
function set_items_grid_fullscreen($wrapper, enable) {
    // Close any other full-screen grid first
    $(".excel-items-grid-fullscreen")
        .not($wrapper)
        .removeClass("excel-items-grid-fullscreen");

    $wrapper.toggleClass("excel-items-grid-fullscreen", enable);
    $("body").toggleClass("excel-items-grid-body-lock", enable);

    const $button = $wrapper.find("> .excel-grid-toolbar .excel-grid-toggle");

    // Update button state
    $button
        .attr("aria-pressed", enable ? "true" : "false")
        .html(`
            <span class="icon">${enable ? "×" : "⛶"}</span>
            <span class="label">${enable ? "Close Full Screen" : "Full Screen"}</span>
        `);

    // Re-measure and focus after transition
    setTimeout(() => {
        mark_items_grid_sticky_columns($wrapper);
        queue_items_grid_header_sync($wrapper);

        if (enable) {
            // Focus the scrollable area for keyboard navigation
            $wrapper.find(".form-grid-container").trigger("focus");
        }
    }, 100);
}

// ============================================================================
// Header Height Synchronization
// ============================================================================

/**
 * Queue a header height re-measurement
 * Allows both label row and filter row to expand naturally,
 * then fixes the container height to prevent layout shift
 * 
 * @param {jQuery} $wrapper - Grid wrapper element
 */
function queue_items_grid_header_sync($wrapper) {
    const old_timer = $wrapper.data("excel-grid-header-sync-timer");

    if (old_timer) clearTimeout(old_timer);

    const timer = setTimeout(() => {
        const heading =
            $wrapper.find(".form-grid-container > .grid-heading-row").get(0) ||
            $wrapper.find(".grid-heading-row").get(0);

        if (!heading) return;

        // Temporarily remove height constraints so we can measure real content
        heading.style.removeProperty("height");
        heading.style.removeProperty("min-height");
        heading.style.setProperty("overflow", "visible", "important");

        requestAnimationFrame(() => {
            // Find all visible rows (label + filter)
            const visible_rows = Array.from(heading.children).filter((element) => {
                return (
                    element.classList.contains("grid-row") &&
                    element.offsetParent !== null
                );
            });

            // Sum their heights
            const measured_height = visible_rows.reduce((total, element) => {
                return total + element.getBoundingClientRect().height;
            }, 0);

            // Fallback for edge cases
            const fallback_height = 46;
            const final_height = Math.max(Math.ceil(measured_height), fallback_height);

            // Apply fixed height
            heading.style.setProperty("height", `${final_height}px`, "important");
            heading.style.setProperty("min-height", `${final_height}px`, "important");

            // Update CSS custom property for dependent calculations
            $wrapper.get(0)?.style.setProperty("--excel-heading-height", `${final_height}px`);
        });
    }, 50);

    $wrapper.data("excel-grid-header-sync-timer", timer);
}

