           ==================================================================== */

        body.excel-items-grid-body-lock {
            overflow: hidden !important;
        }

        .excel-items-grid {
            /* Color scheme */
            --excel-solid-bg: var(--card-bg, var(--fg-color, #ffffff));
            --excel-page-bg: var(--bg-color, #f5f7fa);
            --excel-border: var(--border-color, #d8dce3);
            --excel-accent: var(--primary, #2490ef);
            --excel-soft-shadow: 0 1px 3px rgba(15, 23, 42, 0.06);

            /* Typography */
            --excel-font-size: 11px;
            --excel-font-weight-normal: 400;
            --excel-font-weight-bold: 600;

            /* Colors */
            --excel-label-bg: var(--gray-100, #eef1f6);
            --excel-zebra-bg: #fafbfc;
            --excel-hover-bg: #eaf3ff;
            --excel-focus-ring: 2px solid var(--excel-accent);
            --excel-text-primary: var(--text-color, #1e293b);
            --excel-text-muted: var(--text-muted, #64748b);

            /* Layout dimensions */
            --excel-check-width: 32px;
            --excel-index-width: 40px;
            --excel-item-width: 240px;
            --excel-action-width: 40px;
            --excel-row-height: 34px;
            --excel-grid-min-width: 1550px;

            /* Transitions */
            --excel-transition: all 0.08s cubic-bezier(0.4, 0, 0.2, 1);

            position: relative;
            background: var(--excel-solid-bg);
            font-size: var(--excel-font-size) !important;
            color: var(--excel-text-primary);
        }

        /* Apply typography throughout */
        .excel-items-grid .data-row,
        .excel-items-grid .data-row .col,
        .excel-items-grid .data-row input,
        .excel-items-grid .data-row select,
        .excel-items-grid .data-row .static-area,
        .excel-items-grid .grid-heading-row,
        .excel-items-grid .grid-heading-row .col {
            font-size: var(--excel-font-size) !important;
            line-height: 1.4 !important;
            color: var(--excel-text-primary);
        }

        /* ====================================================================
           Toolbar
           ==================================================================== */

        .excel-items-grid > .excel-grid-toolbar {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 12px;

            min-height: 48px;
            padding: 8px 12px;
            margin-bottom: 8px;

            position: relative;
            z-index: 100;

            background: linear-gradient(
                to bottom,
                var(--excel-solid-bg),
                var(--excel-label-bg)
            ) !important;
            border: 1px solid var(--excel-border);
            border-radius: 8px;
            box-shadow: var(--excel-soft-shadow);
            opacity: 1 !important;
        }

        .excel-grid-toolbar-left {
            display: flex;
            align-items: center;
            gap: 12px;
            min-width: 0;
            flex-wrap: wrap;
        }

        .excel-grid-toolbar-left strong {
            font-weight: var(--excel-font-weight-bold);
            color: var(--excel-text-primary);
        }

        .excel-grid-row-count {
            padding: 2px 10px;
            border-radius: 12px;
            background: var(--excel-accent);
            color: #fff;
            font-size: 11px;
            font-weight: var(--excel-font-weight-bold);
            letter-spacing: 0.2px;
            white-space: nowrap;
            line-height: 1.4;
        }

        .excel-grid-help {
            color: var(--excel-text-muted);
            font-size: 10px;
        }

        .excel-grid-help kbd {
            display: inline-block;
            padding: 2px 4px;
            border: 1px solid var(--excel-border);
            border-radius: 3px;
            background: rgba(100, 116, 139, 0.1);
            font-family: monospace;
            font-size: 10px;
        }

        .excel-grid-toggle {
            display: flex;
            align-items: center;
            gap: 6px;
            min-width: auto;
            min-width: 135px;
            pointer-events: auto !important;
            position: relative;
            z-index: 110;
            border-radius: 6px;
            box-shadow: 0 1px 2px rgba(15, 23, 42, 0.12);
            transition: var(--excel-transition);
