                        overflow: visible !important;
                    }

                    .${NS} ${SELECTORS.DATA_ROW} .form-control,
                    .${NS} ${SELECTORS.DATA_ROW} .awesomplete,
                    .${NS} ${SELECTORS.DATA_ROW} .control-input-wrapper {
                        min-width: 0;
                        width: 100%;
                    }

                    .${NS} .awesomplete > ul,
                    .${NS} [role="listbox"] {
                        z-index: 2400 !important;
                    }

                    .${NS} ${SELECTORS.HEADING_ROW} ${SELECTORS.COL} {
                        position: relative;
                        background: var(--sheet-head) !important;
                        font-weight: 700;
                        color: var(--text-muted);
                    }

                    .${NS}__resize {
                        position: absolute;
                        top: 0;
                        right: -3px;
                        width: 8px;
                        height: 100%;
                        cursor: col-resize;
                        z-index: 30;
                    }

                    .${NS}__resize:hover { background: var(--primary, #2490ef); }

                    .${NS}__totals {
                        position: sticky;
                        bottom: 0;
                        z-index: 14;
                        border-top: 2px solid var(--sheet-border);
                        box-shadow: 0 -3px 8px rgba(15, 23, 42, 0.08);
                        pointer-events: none;
                    }

                    .${NS}__totals ${SELECTORS.DATA_ROW} {
                        background: var(--sheet-total) !important;
                    }

                    .${NS}__total-cell {
                        justify-content: flex-end;
                        text-align: right;
                        font-weight: 800;
                        color: var(--text-color);
                        background: var(--sheet-total) !important;
                    }

                    .${NS}__total-label {
                        justify-content: flex-start;
                        text-align: left;
                        color: var(--text-muted);
                        text-transform: uppercase;
                        letter-spacing: .04em;
                        font-size: 10px;
                    }

                    .${NS}__empty-row {
                        opacity: .92;
                    }

                    .${NS}__filtered-out {
                        display: none !important;
                    }

                    @media (max-width: 900px) {
                        .${NS}__shortcuts,
                        .${NS}__metric { display: none; }
                        .${NS}__toolbar { gap: 6px; }
                        .${NS}__spacer { display: none; }
                        .${NS}__filter {
                            order: 20;
                            flex: 1 1 100%;
                            width: auto;
                        }
                    }
                `,
            }).appendTo('head');
        }

        buildToolbar() {
            if (this.$wrapper.children(`.${NS}__toolbar`).length) return;

            this.$wrapper.prepend(`
                <div class="${NS}__toolbar">
                    <span class="${NS}__title">Items Spreadsheet</span>
                    <span class="${NS}__count">0 rows</span>
                    <span class="${NS}__shortcuts" aria-label="Keyboard shortcuts">
                        <kbd>Ctrl+C</kbd><kbd>Ctrl+V</kbd><kbd>Ctrl+Shift+F</kbd><kbd>Esc</kbd>
                    </span>
                    <button type="button" class="btn btn-primary btn-xs ${NS}__fullscreen"
                        title="Toggle fullscreen (Ctrl+Shift+F)">⛶ Full Screen</button>
                    <span class="${NS}__metric ${NS}__metric-qty">Qty 0</span>
                    <span class="${NS}__metric ${NS}__metric-amount">Amount 0.00</span>
                    <span class="${NS}__spacer"></span>
                    <input class="${NS}__filter" type="search" placeholder="Filter rows..." aria-label="Filter item rows">
                    <button type="button" class="btn btn-default btn-xs ${NS}__columns">Columns</button>
                    <button type="button" class="btn btn-default btn-xs ${NS}__fit">Fit</button>
                    <button type="button" class="btn btn-default btn-xs ${NS}__reset">Reset</button>
                </div>
            `);
        }

        bindEvents() {
            this.$wrapper.off(`.${NS}`);

            this.$wrapper.on(`click.${NS}`, `.${NS}__fit`, () => {
                this.autoFit();
            });

            this.$wrapper.on(`click.${NS}`, `.${NS}__reset`, () => {
                this.widths = {};
                this.visibility = {};
                localStorage.removeItem(STORAGE_KEY);
                localStorage.removeItem(VISIBILITY_KEY);
                this.refresh();
            });

            this.$wrapper.on(`input.${NS}`, `.${NS}__filter`, (event) => {
                this.filterText = event.currentTarget.value || '';
                this.applyFilter();
                this.updateRowCount();
                this.updateTotals();
            });

            this.$wrapper.on(`click.${NS}`, `.${NS}__columns`, (event) => {
                event.preventDefault();
                event.stopPropagation();
                this.toggleColumnMenu(event.currentTarget);
            });

            this.$wrapper.on(`change.${NS}`, `.${NS}__column-toggle`, (event) => {
                const field = event.currentTarget.dataset.fieldname;
                if (!field) return;

                this.visibility[field] = !event.currentTarget.checked;
                U.saveVisibility(this.visibility);
                this.refresh();
            });

            this.$wrapper.on(`click.${NS}`, `.${NS}__fullscreen`, () => {
                this.toggleFullscreen(!this.isFullscreen);
            });

            this.$wrapper.on(`click.${NS}`, `${SELECTORS.BODY} ${SELECTORS.DATA_ROW} > ${SELECTORS.COL}`, (event) => {
                this.setActiveCell(event.currentTarget);
            });

            this.$wrapper.on(`keydown.${NS}`, SELECTORS.GRID_CONTAINER, (event) => {
                this.onGridKeydown(event);
            });

            this.$wrapper.on(
                `input.${NS} change.${NS}`,
                `${SELECTORS.BODY} input, ${SELECTORS.BODY} select, ${SELECTORS.BODY} textarea`,
                () => this.schedule()
            );

            this.$wrapper.on(`mousedown.${NS}`, `.${NS}__resize`, (event) => {
                this.startResize(event);
            });

            this.$wrapper.on(`dblclick.${NS}`, `.${NS}__resize`, (event) => {
                event.preventDefault();
                event.stopPropagation();
                const col = $(event.currentTarget).closest(SELECTORS.COL)[0];
                const index = this.headerCells().index(col);
                this.autoFitColumn(index);
            });
        }

        observeGrid() {
            const body = this.$wrapper.find(SELECTORS.BODY)[0];
            if (!body || this.observer) return;

            this.observer = new MutationObserver(() => this.schedule());
            this.observer.observe(body, { childList: true, subtree: true });
        }

        refresh() {
            if (this.destroyed) return;

            requestAnimationFrame(() => {
                if (!this.isReady()) {
                    setTimeout(() => this.refresh(), 120);
                    return;
                }

                this.prepareGridContainer();
                this.ensureTotalsRow();
                this.syncColumnWidths();
                this.applyVisibility();
                this.classifyRows();
                this.applyFilter();
                this.syncStickyOffsets();
                this.updateRowCount();
                this.updateTotals();
            });
        }

        isReady() {
            return this.$wrapper.find(SELECTORS.GRID_CONTAINER).length &&
                this.headerCells().length;
        }

        headerCells() {
            return this.$wrapper
                .find(`${SELECTORS.HEADING_ROW} ${SELECTORS.DATA_ROW}`)
                .first()
                .children(SELECTORS.COL);
        }

        bodyRows() {
            return this.$wrapper.find(`${SELECTORS.BODY} ${SELECTORS.GRID_ROW}`);
        }

        rowCells(row) {
            return $(row).find(`${SELECTORS.DATA_ROW} > ${SELECTORS.COL}`);
        }

        prepareGridContainer() {
            this.$wrapper
                .find(SELECTORS.GRID_CONTAINER)
                .attr('tabindex', '0')
                .attr('role', 'grid')
                .attr('aria-label', 'Purchase Order items spreadsheet');
        }

        toggleFullscreen(enable) {
            this.isFullscreen = !!enable;
            this.$wrapper.toggleClass(`${NS}--fullscreen`, this.isFullscreen);
            $('body').toggleClass(`${NS}--locked`, this.isFullscreen);
            this.$wrapper
                .find(`.${NS}__fullscreen`)
                .text(this.isFullscreen ? '× Exit Full Screen' : '⛶ Full Screen')
                .attr('aria-pressed', this.isFullscreen ? 'true' : 'false');

            setTimeout(() => this.refresh(), 40);
        }

        onDocumentKeydown(event) {
            if ((event.ctrlKey || event.metaKey) && event.shiftKey && event.key.toLowerCase() === 'f') {
                event.preventDefault();
                this.toggleFullscreen(!this.isFullscreen);
                return;
            }

            if (event.key === 'Escape' && this.isFullscreen) {
                event.preventDefault();
                this.toggleFullscreen(false);
            }

            if (event.key === 'Escape') {
                this.hideColumnMenu();
            }
        }

        onDocumentClick(event) {
            if ($(event.target).closest(`.${NS}__column-menu, .${NS}__columns`).length) return;
            this.hideColumnMenu();
        }

        toggleColumnMenu(button) {
            if (this.$columnMenu && this.$columnMenu.length) {
                this.hideColumnMenu();
                return;
            }

            const headers = this.headerCells().toArray()
                .map((col, index) => {
                    const field = this.fieldname(col);
                    if (!field) return null;
                    return {
                        field,
                        label: this.docfield(field)?.label || U.headerText(col) || field,
                        checked: !this.visibility[field],
                        index,
                    };
                })
                .filter(Boolean);

            const html = `
                <div class="${NS}__column-menu" role="menu">
                    <div class="${NS}__column-menu-title">Visible Columns</div>
                    ${headers.map((item) => `
                        <label class="${NS}__column-option">
                            <input class="${NS}__column-toggle" type="checkbox"
                                data-fieldname="${U.escapeHtml(item.field)}"
                                ${item.checked ? 'checked' : ''}>
                            <span>${U.escapeHtml(item.label)}</span>
                        </label>
                    `).join('')}
                </div>
            `;

            this.$columnMenu = $(html).appendTo(document.body);
            const rect = button.getBoundingClientRect();
            const menu = this.$columnMenu[0];
            const left = Math.max(8, Math.min(rect.left, window.innerWidth - menu.offsetWidth - 8));
            const top = Math.max(8, Math.min(rect.bottom + 6, window.innerHeight - menu.offsetHeight - 8));
            this.$columnMenu.css({ left, top });
        }

        hideColumnMenu() {
            if (!this.$columnMenu) return;
            this.$columnMenu.remove();
            this.$columnMenu = null;
        }

        onGridKeydown(event) {
            if (event.ctrlKey || event.metaKey) {
                if (event.key.toLowerCase() === 'c') {
                    event.preventDefault();
                    this.copyActiveCell();
                    return;
                }

                if (event.key.toLowerCase() === 'v') {
                    event.preventDefault();
                    this.pasteIntoActiveCell();
                    return;
                }
            }

            const moves = {
                ArrowLeft: [0, -1],
                ArrowRight: [0, 1],
                ArrowUp: [-1, 0],
                ArrowDown: [1, 0],
            };

            if (moves[event.key]) {
                event.preventDefault();
                this.moveActiveCell(moves[event.key][0], moves[event.key][1]);
                return;
            }

            if (event.key === 'Enter' && this.activeCell) {
                const row = this.bodyRows().get(this.activeCell.rowIndex);
                const openButton = row && $(row).find('.btn-open-row').get(0);
                if (openButton) {
                    event.preventDefault();
                    openButton.click();
                }
            }
        }

        setActiveCell(cell) {
            if (!cell) return;

            this.$wrapper.find(`.${NS}__active-cell`).removeClass(`${NS}__active-cell`);
            cell.classList.add(`${NS}__active-cell`);

            const row = $(cell).closest(SELECTORS.GRID_ROW)[0];
            const rowIndex = this.bodyRows().index(row);
            const colIndex = $(cell).closest(SELECTORS.DATA_ROW).children(SELECTORS.COL).index(cell);
            this.activeCell = { rowIndex, colIndex, cell };
            this.$wrapper.find(SELECTORS.GRID_CONTAINER).trigger('focus');
        }

        moveActiveCell(rowDelta, colDelta) {
            if (!this.activeCell) {
                const firstCell = this.visibleRows().first().find(`${SELECTORS.DATA_ROW} > ${SELECTORS.COL}:not(.${NS}__hidden-col)`).get(0);
                this.setActiveCell(firstCell);
                return;
            }

            const rows = this.visibleRows();
            const currentVisibleRow = rows.index(this.bodyRows().get(this.activeCell.rowIndex));
            const visibleRowIndex = Math.max(0, Math.min(rows.length - 1, currentVisibleRow + rowDelta));
            const row = rows.get(visibleRowIndex);
            const cells = row ? this.rowCells(row).not(`.${NS}__hidden-col`) : $();
            const currentVisibleCol = cells.index(this.activeCell.cell);
            const visibleColIndex = Math.max(0, Math.min(cells.length - 1, currentVisibleCol + colDelta));
            const nextCell = cells.get(visibleColIndex);

            if (nextCell) {
                this.setActiveCell(nextCell);
                nextCell.scrollIntoView({ block: 'nearest', inline: 'nearest' });
            }
        }

        visibleRows() {
            return this.bodyRows().not(`.${NS}__filtered-out`);
        }

        async copyActiveCell() {
            if (!this.activeCell) return;

            const field = this.fieldAtIndex(this.activeCell.colIndex);
            const row = this.frm.doc.items && this.frm.doc.items[this.activeCell.rowIndex];
            if (!field || !row) return;

            const value = row[field] == null ? '' : String(row[field]);
            await navigator.clipboard?.writeText(value);
            frappe.show_alert({ message: 'Copied', indicator: 'green' }, 2);
        }

        async pasteIntoActiveCell() {
            if (!this.activeCell) return;

            let text = '';
            try {
                text = await navigator.clipboard.readText();
            } catch (error) {
                frappe.show_alert({ message: 'Clipboard paste was blocked by the browser', indicator: 'orange' }, 4);
                return;
            }

            const rows = text.split(/\r?\n/).filter((line) => line.length);
            const updates = [];

            rows.forEach((line, rowOffset) => {
                const item = this.frm.doc.items && this.frm.doc.items[this.activeCell.rowIndex + rowOffset];
                if (!item) return;

                line.split('\t').forEach((value, colOffset) => {
                    const field = this.fieldAtVisibleOffset(this.activeCell.colIndex, colOffset);
                    const df = this.docfield(field);
                    if (!field || !df || df.read_only) return;

                    updates.push(frappe.model.set_value(item.doctype, item.name, field, value.trim()));
                });
            });

            await Promise.all(updates);
            this.frm.refresh_field('items');
            this.schedule();
            frappe.show_alert({ message: 'Pasted', indicator: 'green' }, 2);
        }

        fieldAtIndex(index) {
            const col = this.headerCells().get(index);
            return this.fieldname(col);
        }

        fieldAtVisibleOffset(startIndex, offset) {
            const visibleHeaders = this.headerCells().toArray()
                .map((col, index) => ({ col, index }))
                .filter((entry) => !entry.col.classList.contains(`${NS}__hidden-col`));
            const startVisibleIndex = visibleHeaders.findIndex((entry) => entry.index === startIndex);
            const target = visibleHeaders[startVisibleIndex + offset];
            return target ? this.fieldname(target.col) : '';
        }

        updateRowCount() {
            const rows = Array.isArray(this.frm.doc.items) ? this.frm.doc.items.length : 0;
            const visible = this.filterText ? this.visibleRowIndexes().length : rows;
            const label = this.filterText && visible !== rows ?
                `${visible}/${rows} rows` :
                `${rows} ${rows === 1 ? 'row' : 'rows'}`;
            this.$wrapper.find(`.${NS}__count`).text(label);
        }

        visibleRowIndexes() {
            const indexes = [];
            this.bodyRows().each((index, row) => {
                if (!row.classList.contains(`${NS}__filtered-out`)) {
                    indexes.push(index);
                }
            });
            return indexes;
        }

        classifyRows() {
            const items = Array.isArray(this.frm.doc.items) ? this.frm.doc.items : [];
            this.bodyRows().each((index, row) => {
                const item = items[index] || {};
                const isEmpty = !item.item_code && !item.item_name;
                row.classList.toggle(`${NS}__empty-row`, isEmpty);
            });
        }

        applyFilter() {
            const needle = U.normalize(this.filterText);
            const fields = this.headerCells().toArray()
                .map((col) => this.fieldname(col))
                .filter(Boolean);
            const items = Array.isArray(this.frm.doc.items) ? this.frm.doc.items : [];

            this.bodyRows().each((index, row) => {
                if (!needle) {
                    row.classList.remove(`${NS}__filtered-out`);
                    return;
                }

                const item = items[index] || {};
                const haystack = fields.map((field) => item[field]).join(' ');
                row.classList.toggle(`${NS}__filtered-out`, !U.normalize(haystack).includes(needle));
            });
        }

        applyVisibility() {
            this.headerCells().each((index, col) => {
                const key = this.columnKey(col, index);
                const field = this.fieldname(col);
                const hidden = !!(field && this.visibility[field]);
                this.columnCells(index).toggleClass(`${NS}__hidden-col`, hidden);
                this.$wrapper.find(`.${NS}__total-row > ${SELECTORS.COL}`).eq(index)
                    .toggleClass(`${NS}__hidden-col`, hidden);
            });
        }

        columnCells(index) {
            const cells = [];
            const header = this.headerCells().get(index);
            if (header) cells.push(header);
            this.bodyRows().each((_, row) => {
                const cell = this.rowCells(row).get(index);
                if (cell) cells.push(cell);
            });
            const total = this.$wrapper.find(`.${NS}__total-row > ${SELECTORS.COL}`).get(index);
            if (total) cells.push(total);
            return $(cells);
        }

        syncStickyOffsets() {
            const headers = this.headerCells();
            this.$wrapper
                .find(`.${NS}__sticky-left, .${NS}__sticky-right`)
                .removeClass(`${NS}__sticky-left ${NS}__sticky-right`)
                .css({ left: '', right: '' });

            let left = 0;
            headers.each((index, col) => {
                const key = this.columnKey(col, index);
                const field = this.fieldname(col);
                if ((field && this.visibility[field]) || !STICKY_LEFT_KEYS.includes(key)) return;

                const width = this.widthFor(col, key);
                this.columnCells(index).addClass(`${NS}__sticky-left`).css('left', `${left}px`);
                left += width;
            });

            let right = 0;
            $(headers.toArray().reverse()).each((_, col) => {
                const index = headers.index(col);
                const key = this.columnKey(col, index);
                const field = this.fieldname(col);
                if ((field && this.visibility[field]) || !STICKY_RIGHT_KEYS.includes(key)) return;

                const width = this.widthFor(col, key);
                this.columnCells(index).addClass(`${NS}__sticky-right`).css('right', `${right}px`);
                right += width;
            });
        }

        ensureTotalsRow() {
            const container = this.$wrapper.find(SELECTORS.GRID_CONTAINER).first();
            if (!container.length) return;

            let totals = container.children(`.${NS}__totals`);
            if (!totals.length) {
                totals = $(`<div class="${NS}__totals"><div class="data-row ${NS}__total-row"></div></div>`);
                container.append(totals);
            }

            const row = totals.find(`.${NS}__total-row`);
            const headers = this.headerCells();

            if (row.children().length !== headers.length) {
                row.empty();
                headers.each((index, col) => {
                    const cell = $('<div class="col grid-static-col"></div>')
                        .addClass(`${NS}__total-cell`)
                        .attr('data-total-index', index);
                    row.append(cell);
                });
            }

            headers.each((index, col) => {
                const field = this.fieldname(col);
                const cell = row.children(SELECTORS.COL).get(index);
                if (!cell) return;

                if (field) {
                    cell.dataset.fieldname = field;
                } else {
                    delete cell.dataset.fieldname;
                }
                cell.dataset.totalIndex = String(index);
            });
        }

        syncColumnWidths() {
            const headers = this.headerCells();
            let gridWidth = 0;

            headers.each((index, col) => {
                const key = this.columnKey(col, index);
                const width = this.widthFor(col, key);
                gridWidth += width;

                this.setCellWidth(col, width);
                this.ensureResizeHandle(col);

                this.bodyRows().each((_, row) => {
                    const cell = $(row).children(SELECTORS.DATA_ROW).children(SELECTORS.COL).get(index) ||
                        $(row).find(`${SELECTORS.DATA_ROW} > ${SELECTORS.COL}`).get(index);
                    this.setCellWidth(cell, width);
                });

                const totalCell = this.$wrapper.find(`.${NS}__total-row > ${SELECTORS.COL}`).get(index);
                this.setCellWidth(totalCell, width);
            });

            this.$wrapper
                .find(`${SELECTORS.HEADING_ROW} ${SELECTORS.DATA_ROW}, ${SELECTORS.BODY} ${SELECTORS.DATA_ROW}, .${NS}__total-row`)
                .css({
                    width: `${gridWidth}px`,
                    minWidth: `${gridWidth}px`,
                });
        }

        setCellWidth(cell, width) {
            if (!cell) return;

            $(cell).css({
                flexBasis: `${width}px`,
                width: `${width}px`,
                minWidth: `${width}px`,
                maxWidth: `${width}px`,
            });
        }

        ensureResizeHandle(col) {
            if ($(col).children(`.${NS}__resize`).length) return;
            $('<span class="' + NS + '__resize" aria-hidden="true"></span>').appendTo(col);
        }

        startResize(event) {
            event.preventDefault();
            event.stopPropagation();

            const col = $(event.currentTarget).closest(SELECTORS.COL)[0];
            const headers = this.headerCells();
            const index = headers.index(col);
            const key = this.columnKey(col, index);
            const startX = event.clientX;
            const startWidth = col.getBoundingClientRect().width || this.widthFor(col, key);

            const onMove = (moveEvent) => {
                const next = Math.max(MIN_WIDTH, Math.min(MAX_WIDTH, startWidth + moveEvent.clientX - startX));
                this.widths[key] = Math.round(next);
                U.saveWidths(this.widths);
                this.syncColumnWidths();
                this.syncStickyOffsets();
            };

            const onUp = () => {
                document.removeEventListener('mousemove', onMove);
                document.removeEventListener('mouseup', onUp);
                this.updateTotals();
            };

            document.addEventListener('mousemove', onMove);
            document.addEventListener('mouseup', onUp);
        }

        autoFit() {
            this.headerCells().each((index, col) => {
                this.widths[this.columnKey(col, index)] = this.measuredColumnWidth(index, col);
            });

            U.saveWidths(this.widths);
            this.refresh();
        }

        autoFitColumn(index) {
            const col = this.headerCells().get(index);
            if (!col) return;

            this.widths[this.columnKey(col, index)] = this.measuredColumnWidth(index, col);
            U.saveWidths(this.widths);
            this.refresh();
        }

        measuredColumnWidth(index, col) {
            let width = Math.max(this.defaultWidth(col), col.scrollWidth + 18);

            this.bodyRows().slice(0, 100).each((_, row) => {
                const cell = this.rowCells(row).get(index);
                if (cell) width = Math.max(width, cell.scrollWidth + 18);
            });

            return Math.max(MIN_WIDTH, Math.min(MAX_WIDTH, Math.ceil(width)));
        }

        updateTotals() {
            const allItems = Array.isArray(this.frm.doc.items) ? this.frm.doc.items : [];
            const visibleIndexes = this.visibleRowIndexes();
            const items = this.filterText ?
                visibleIndexes.map((index) => allItems[index]).filter(Boolean) :
                allItems;
            const headers = this.headerCells();
            const labelField = this.findLabelField(headers);
            const totalCells = this.$wrapper.find(`.${NS}__total-row > ${SELECTORS.COL}`);
            const totalQty = items.reduce((sum, row) => sum + U.toFloat(row.qty || row.stock_qty || row.quantity), 0);
            const totalAmount = this.bestAmountTotal(items);

            this.$wrapper.find(`.${NS}__metric-qty`).text(`Qty ${U.format(totalQty, totalQty % 1 ? 4 : 0)}`);
            this.$wrapper.find(`.${NS}__metric-amount`).text(`Amount ${U.format(totalAmount, 2)}`);

            headers.each((index, col) => {
                const cell = totalCells.get(index);
                if (!cell) return;

                const field = this.fieldname(col);
                const df = this.docfield(field);
                const label = df && df.label ? df.label : U.headerText(col);

                cell.textContent = '';
                cell.title = '';
                cell.classList.toggle(`${NS}__total-label`, field === labelField);

                if (field === labelField) {
                    cell.textContent = this.filterText && items.length !== allItems.length ?
                        `Subtotal (${items.length}/${allItems.length})` :
                        'Totals';
                    return;
                }

                if (!this.shouldTotal(field, label, df)) return;

                const total = items.reduce((sum, row) => {
                    return sum + this.valueFor(row, field, label);
                }, 0);
                const normalized = Math.abs(total) < 1e-9 ? 0 : total;
                const precision = this.precisionFor(field, df, items);
                const formatted = U.format(normalized, precision);

                cell.textContent = formatted;
                cell.title = `${label || field}: ${formatted}`;
            });
        }

        bestAmountTotal(items) {
            const fields = ['amount', 'base_amount', 'net_amount', 'custom_line_total', 'custom_amount_pkr'];
            const field = fields.find((candidate) => items.some((row) => U.toFloat(row && row[candidate])));
            if (!field) return 0;
            return items.reduce((sum, row) => sum + U.toFloat(row && row[field]), 0);
        }

        findLabelField(headers) {
            for (const field of LABEL_FIELDS) {
                const found = headers.toArray().find((col) => this.fieldname(col) === field);
                if (found) return field;
            }

            const found = headers.toArray().find((col) => {
                const field = this.fieldname(col);
                const df = this.docfield(field);
                return field && !this.shouldTotal(field, df && df.label, df);
            });

            return found ? this.fieldname(found) : '';
        }

        shouldTotal(field, label, df) {
            if (!field) return false;

            const text = `${field} ${label || ''}`.toLowerCase();
            const hinted = TOTAL_HINTS.some((hint) => text.includes(hint));
            const excluded = TOTAL_EXCLUDES.some((hint) => text.includes(hint));
            const amountOrQty = /(amount|total|qty|quantity|taxable_value|taxable_amount)/.test(text);
            const numeric = df && ['Currency', 'Float', 'Int'].includes(df.fieldtype);

            if (excluded && !amountOrQty) return false;
            return hinted || (numeric && amountOrQty);
        }

        valueFor(row, field, label) {
            if (!row) return 0;

            const value = row[field];
            if (this.isGrossField(field, label)) {
                const raw = U.toFloat(value);
                const computed = this.computedGross(row);
                if ((value === undefined || value === null || value === '' || raw === 0) && computed) {
                    return computed;
                }
            }

            return U.toFloat(value);
        }

        computedGross(row) {
            const qty = U.toFloat(row.qty || row.quantity || row.stock_qty);
            const rate = U.toFloat(row.vendor_rate || row.custom_vendor_rate || row.rate || row.base_rate || row.price_list_rate);
            return qty && rate ? qty * rate : 0;
        }

        isGrossField(field, label) {
            return /(gross.*total|gross.*amount|line.*total)/i.test(`${field} ${label || ''}`);
        }

        precisionFor(field, df, items) {
            const metaPrecision = Number.parseInt(df && df.precision, 10);
            if (Number.isFinite(metaPrecision)) return metaPrecision;

            if (/qty|quantity/i.test(field)) return 0;

            const sample = items.reduce((places, row) => {
                const value = this.valueFor(row, field, df && df.label);
                const match = String(value).match(/\.(\d+)/);
                const decimals = match ? match[1].replace(/0+$/, '').length : 0;
                return Math.max(places, decimals);
            }, 0);
            if (sample) return Math.min(sample, 6);

            const sysPrecision = Number.parseInt(frappe.boot && frappe.boot.sysdefaults && frappe.boot.sysdefaults.currency_precision, 10);
            return Number.isFinite(sysPrecision) ? sysPrecision : 2;
        }

        widthFor(col, key) {
            return this.widths[key] || this.defaultWidth(col, key);
        }

        defaultWidth(col, key) {
            const field = this.fieldname(col);
            if (WIDTHS[key]) return WIDTHS[key];
            if (field && WIDTHS[field]) return WIDTHS[field];

            const label = U.headerText(col);
            return Math.max(74, Math.min(180, (label.length * 8) + 32));
        }

        columnKey(col, index) {
            const field = this.fieldname(col);
            if (field) return field;
            if (col.classList.contains('row-check')) return 'row_check';
            if (col.classList.contains('row-index')) return 'row_index';
            if (col.classList.contains('btn-open-row')) return 'btn_open_row';
            return `col_${index}`;
        }

        fieldname(col) {
            return col && col.dataset ? (col.dataset.fieldname || '') : '';
        }

        docfield(field) {
            if (!field || !this.grid) return null;
            if (this.grid.fields_map && this.grid.fields_map[field]) return this.grid.fields_map[field];
            if (Array.isArray(this.grid.docfields)) {
                return this.grid.docfields.find((df) => df.fieldname === field) || null;
            }
            if (frappe.meta && frappe.meta.get_docfield) {
                return frappe.meta.get_docfield('Purchase Order Item', field, this.frm.doc.name);
            }
            return null;
        }

        destroy() {
            this.destroyed = true;
            if (this.observer) this.observer.disconnect();
            document.removeEventListener('keydown', this.boundDocumentKeydown);
            document.removeEventListener('click', this.boundDocumentClick);
            this.hideColumnMenu();
            $('body').removeClass(`${NS}--locked`);
            this.$wrapper.off(`.${NS}`);
            this.$wrapper.removeClass(`${NS} ${INSTANCE_CLASS} ${NS}--fullscreen`).removeData(NS);
            this.$wrapper.children(`.${NS}__toolbar`).remove();
            this.$wrapper.find(`.${NS}__totals`).remove();
            this.$wrapper.find(`.${NS}__resize`).remove();
        }
    }

    function install(frm) {
        if (!frm || frm.doctype !== 'Purchase Order') return;

        if (frm._po_items_sheet) {
            const currentWrapper = frm.fields_dict.items &&
                frm.fields_dict.items.grid &&
                frm.fields_dict.items.grid.wrapper;
            const oldWrapper = frm._po_items_sheet.$wrapper &&
                frm._po_items_sheet.$wrapper[0];

            if (currentWrapper === oldWrapper && document.body.contains(oldWrapper)) {
                frm._po_items_sheet.refresh();
                return;
            }

            frm._po_items_sheet.destroy();
            frm._po_items_sheet = null;
        }

        frm._po_items_sheet = new PurchaseOrderItemsSheet(frm);
        frm._po_items_sheet.mount();
    }

    function refreshParent(frm) {
        if (frm && frm._po_items_sheet) frm._po_items_sheet.schedule();
    }

    frappe.ui.form.on('Purchase Order', {
        onload_post_render: install,
        refresh: install,
        items_add: refreshParent,
        items_remove: refreshParent,
        validate: refreshParent,
    });

    frappe.ui.form.on('Purchase Order Item', {
        qty: refreshParent,
        rate: refreshParent,
        vendor_rate: refreshParent,
        custom_vendor_rate: refreshParent,
        amount: refreshParent,
        base_amount: refreshParent,
        net_amount: refreshParent,
        gross_total: refreshParent,
        gross_amount: refreshParent,
        discount_amount: refreshParent,
        scheme_qty: refreshParent,
        form_render: refreshParent,
    });

    $(document)
        .off(`page-change.${NS}`)
        .on(`page-change.${NS}`, () => {
            $(`.${NS}`).each(function () {
                const instance = $(this).data(NS);
                if (instance) instance.destroy();
            });
        });
})();

frappe.ui.form.on('Purchase Receipt', {
    refresh: function (frm) {
        if (frm.doc.docstatus !== 1) {
            return;
        }

        if (frm.doc.custom_branch_price_update_status !== 'Updated') {
            frm.add_custom_button('Update Branch Price', function () {
                call_shelf_price_update(frm, 'aimatic.shelf_pricing.api.apply_branch_price_update');
            });
        }

        if (frm.doc.custom_foodpanda_price_update_status !== 'Updated') {
            frm.add_custom_button('Update Foodpanda Price', function () {
                call_shelf_price_update(frm, 'aimatic.shelf_pricing.api.apply_foodpanda_price_update');
            });
        }
    },

    on_submit: function (frm) {
        frappe.confirm(
            __('Update branch selling price for this receipt?'),
            function () {
                call_shelf_price_update(
                    frm,
                    'aimatic.shelf_pricing.api.apply_branch_price_update',
                    function () {
                        prompt_foodpanda_update(frm);
                    }
                );
            },
            function () {
                frappe.call({
                    method: 'aimatic.shelf_pricing.api.skip_branch_price_update',
                    args: { purchase_receipt: frm.doc.name },
                    callback: function () {
                        prompt_foodpanda_update(frm);
                    },
                });
            }
        );
    },
});

function prompt_foodpanda_update(frm) {
    frappe.confirm(
        __('Update Foodpanda price for this receipt?'),
        function () {
            call_shelf_price_update(frm, 'aimatic.shelf_pricing.api.apply_foodpanda_price_update');
        },
        function () {
            frappe.call({
                method: 'aimatic.shelf_pricing.api.skip_foodpanda_price_update',
                args: { purchase_receipt: frm.doc.name },
                callback: function () {
                    frm.reload_doc();
                },
            });
        }
    );
}

function call_shelf_price_update(frm, method, then) {
    frappe.call({
        method: method,
        args: { purchase_receipt: frm.doc.name },
        freeze: true,
        callback: function (r) {
            if (!r.exc) {
                frm.reload_doc();
            }
            if (then) {
                then(frm);
            }
        },
    });
}
